    {'name': 'Asahina Fire Sculptors', 'clan': 'Crane', 'category': 'alternate', 'keywords': ['Shugenja, Artisan'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Rank 2. Replaces: Any Shugenja 2. Requires: Fire 3, Artisan (Sculpture) 2. Create fleeting sculptures of fire, heat, light, or smoke.', 'techniques': [{'rank': 0, 'name': 'The Inner Shape of Fire', 'effect': 'Expend Fire spell slot, Artisan (Sculpture)/Fire roll (base TN 20): create fire sculpture lasting Fire Ring minutes requiring full concentration. GM awards Glory points for successful performance.'}]},
    {'name': 'Crane Elite Spearman', 'clan': 'Crane', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Daidoji Iron Warrior 2 or Daidoji Scout 2. Requires: Spears 3. Daidoji spear tradition: exploit numerical disadvantage with superior reach.', 'techniques': [{'rank': 0, 'name': 'Talons of the Daidoji', 'effect': 'When attacking with spear, if you strike an opponent who has not yet acted this Round, they must make two Raises to attack you for the remainder of the Round.'}]},
