    {'name': 'Daidoji Spymaster', 'clan': 'Crane', 'category': 'alternate', 'keywords': ['Courtier/Ninja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': "Rank 3. Replaces: Daidoji Iron Warrior 3, Daidoji Scout 3, or Doji Courtier 3. Requires: Crafty Advantage or Honor 4.0 or less. Must be Daidoji. Run the clan's information networks.", 'techniques': [{'rank': 0, 'name': 'Truth in Shadows', 'effect': 'Gain Spy Network Advantage free (or use existing one twice as often). +2k0 to Stealth, Investigation, and Temptation. Lose only half Honor (rounded up) for moderately dishonorable actions on behalf of the Crane.'}]},
    {'name': 'Daidoji Trading Council', 'clan': 'Crane', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Doji Courtier 3, Doji Magistrate 3, Daidoji Iron Warrior 3, or Daidoji Scout 3. Requires: Commerce (Merchant) 3 and either Gentry or Wealthy.', 'techniques': [{'rank': 0, 'name': 'The Golden Path', 'effect': 'Once per month, wage commercial warfare: Contested Commerce/Awareness. Win: opponent loses koku equal to margin. Lose: you lose half that. May purchase Gentry/Wealthy/Servants for 1 less XP.'}]},
    {'name': 'Doji Apologist', 'clan': 'Crane', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Rank 4. Replaces: Doji Courtier 4. Requires: Etiquette (Courtesy) 5. Cover for the errors of comrades and allies.', 'techniques': [{'rank': 0, 'name': 'All Is Forgiven', 'effect': 'Etiquette (Courtesy)/Awareness (TN 25) to erase a Minor Breach. 2 Raises to reduce Major to Minor. 5 Raises to reduce Blasphemous to Major. Minor: act within 2×Insight Rank hours. Major: within that many minutes. Blasphemous: immediately. Cannot cover for own errors.'}]},
    {'name': 'Doji Innocents', 'clan': 'Crane', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Doji Courtier 3. Requires: Honor 5.0+, Sincerity (Honesty) 4. Win allies through radical honesty rather than favors.', 'techniques': [{'rank': 0, 'name': 'The Power of Innocence', 'effect': 'When telling the truth instead of lying for advantage, Sincerity (Honesty)/Awareness vs Investigation/Perception: success impresses target, gaining them as 1-point Devotion Ally. Each success increases Devotion by 1 (max 4). Knowingly lying costs 2 Honor points and disables technique for one month.'}]},
    {'name': 'Doji Marines', 'clan': 'Crane', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Rank 3. Replaces: Doji Magistrate 3 or Daidoji Iron Warrior 4. Requires: Sailing 3. Naval combat and boarding actions: created by Doji Chomei to counter Mantis fleet dominance.', 'techniques': [{'rank': 0, 'name': "Chomei's Courage", 'effect': 'No TN penalties for fighting on slick, irregular, or moving surfaces. In Attack or Full Attack Stance where such a penalty would apply, +Xk0 to melee attacks where X = Reflexes.'}]},
    {'name': 'Doji Warrior-Poet', 'clan': 'Crane', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Kakita Bushi 2. Requires: Iaijutsu 2, Artisan: Poetry 2. The Doji tradition of sword and art as equals.', 'techniques': [{'rank': 0, 'name': 'Fan & Sword', 'effect': 'Spending Void on Iaijutsu or Artisan: Poetry rolls grants +2k1 instead of +1k1. Winning a duel or poetry contest grants +1 Glory point (and champion gains +1 Glory point too if championing someone).'}]},
    {'name': 'Empress Guard', 'clan': 'Crane', 'category': 'alternate', 'keywords': ['Bushi', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': "Replaces: Kakita Bushi 3 or Daidoji Iron Warrior 4. Requires: Perception 3. Elite protection for the Empress: the Crane's finest warriors.", 'techniques': [{'rank': 0, 'name': 'To Defend Unto Death', 'effect': 'Add half Honor Rank to all attack and Perception rolls. While defending Imperial family, +10 Armor TN.'}]},
