    {'name': 'Mirumoto Taoist Swordsman', 'clan': 'Dragon', 'category': 'basic', 'keywords': ['Bushi', 'EE'], 'benefit': '+1 Void', 'skills': 'Athletics, Defense, Iaijutsu, Kenjutsu (Katana), Lore: Theology, Meditation, any 1 Bugei or High Skill', 'honor': '5.5', 'outfit': 'Sturdy Clothing, Katana, Wakizashi, Tanto, Traveling Pack, 1 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Aligned With the Elements', 'effect': 'Sword with no armor: Reduction equal to School Rank +2. +1k0 sword damage.'}, {'rank': 2, 'name': 'Fist and Blade', 'effect': 'Knockdown costs 1 less Raise with sword. Inflict sword damage while controlling Grapple with sword.'}, {'rank': 3, 'name': 'Strike of Harmony', 'effect': 'Spend Void Point on damage rolls while wielding sword (stacks with natural katana ability).'}, {'rank': 4, 'name': 'Master of Steel', 'effect': 'Attack as Simple Action while wielding a sword.'}, {'rank': 5, 'name': 'Balance of Nothingness', 'effect': 'Once per skirmish, spend as many Void Points on damage as desired while wielding sword.'}]},
    {'name': 'Tamori Shugenja', 'clan': 'Dragon', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Stamina', 'skills': 'Athletics, Calligraphy (Cipher), Defense, Divination, Lore: Theology, Medicine, Spellcraft', 'honor': '4.5', 'outfit': 'Robes, Wakizashi, any 1 weapon, Scroll Satchel, Traveling Pack, 5 koku', 'affinity': 'Earth / Air | Starting Spells: Sense, Commune, Summon, 3 Earth, 2 Fire, 1 Water', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'Flesh of the Elements', 'effect': 'Expend one spell slot to store a single-target spell in a potion. Anyone activates it: Simple Action to drink, Complex Action to throw. Counts against daily spell slots while stored. Creation takes Mastery Level hours. Free Raise on Craft keyword spells.'}]},
    {'name': 'The Hitomi Kikage Zumi Order', 'clan': 'Dragon', 'category': 'basic', 'keywords': ['Monk', 'IH'], 'benefit': '+1 Reflexes | Skills: Athletics, Defense, Jiujutsu, Lore (choose one), Meditation, any 2 Non-Low Skills', 'skills': '', 'honor': '4.5', 'outfit': 'Sturdy Clothing, Traveling Pack, 4 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': '', 'effect': 'Gain 1 Tattoo. Add Reflexes to Armor TN. May use Reflexes instead of Strength in Grapple control.'}, {'rank': 2, 'name': '', 'effect': 'Spend Void Point on unarmed damage rolls including Grapple.'}, {'rank': 3, 'name': '', 'effect': 'Unarmed attacks as Simple Action. Gain one Tattoo.'}, {'rank': 4, 'name': '', 'effect': 'Knockdown costs 1 less Raise unarmed. +1k1 to all unarmed damage including Grapple.'}, {'rank': 5, 'name': '', 'effect': 'Knockdown with 2 extra Raises also Stuns. Throwing in Grapple: opponent rolls Earth (TN 20) or Stunned. Gain 1 Tattoo.'}]},
