    {'name': 'Mirumoto Master Sensei', 'clan': 'Dragon', 'category': 'advanced', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Tiny elite: seldom exceeding two dozen total. True mastery of swordsmanship, body, and soul. Cannot be Brash or Proud. Requires Air 5, Earth 4, Void 5, Kenjutsu 5, Meditation 6. Must be chosen and taught by existing Master Sensei.', 'techniques': [{'rank': 1, 'name': 'The Sword and the Soul', 'effect': 'Reduce opponent to Down/Out/Dead with sword: regain 1 Void Point (can temporarily exceed Void Ring, excess vanishes at end of skirmish).'}, {'rank': 2, 'name': 'The Body is Illusion', 'effect': 'Simple Action, spend Void Point: ignore Wound Penalties (including Down, not Out) for rest of skirmish or 10 minutes outside.'}, {'rank': 3, 'name': 'Sword of the Sensei', 'effect': 'Once per day, Simple Action: Meditation/Awareness (TN 25 + 5 per ally): success grants allies benefit of Rank 1 for the skirmish.'}]},
    {'name': 'Swordmasters', 'clan': 'Dragon', 'category': 'advanced', 'keywords': ['Bushi', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': "Evolution of Niten: master every aspect of the two-sword style for any battlefield situation. Pragmatic combat focus vs Kenshinzen's duel focus. Requires Fire 4, Void 4, Iaijutsu 5, Kenjutsu 5, Lore: Theology 4.", 'techniques': [{'rank': 1, 'name': 'The Silence of Two Strikes', 'effect': 'While wielding katana/wakizashi, may spend Void Points twice per Turn.'}, {'rank': 2, 'name': "Mirumoto's Strength", 'effect': 'In iaijutsu duel, always gain +1k1 to Focus roll as if beaten opponent in Assessment, regardless of actual result.'}, {'rank': 3, 'name': 'Harmony and Precision', 'effect': "While wielding katana/wakizashi, ignore opponent's Reduction entirely."}]},
    {'name': 'Tamori Master of the Mountain', 'clan': 'Dragon', 'category': 'advanced', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Loose organization dating to Agasha mountain explorations. Prefer impetuous, self-reliant shugenja: teach them to channel anger into power. Requires one Ring at 4, two other Rings at 3, Spellcraft 5.', 'techniques': [{'rank': 1, 'name': 'Integration of the Gods', 'effect': 'Spend 2 spell slots of another Ring instead of 1 correct Ring (cannot use opposing elements).'}, {'rank': 2, 'name': 'Inner Fortitude', 'effect': 'School Rank +1. Spend spell slot as Free Action: Reduction 2 and +10 Armor TN for Earth Ring Rounds. While active, must call one Raise to no effect each time you cast.'}, {'rank': 3, 'name': 'Power in Need', 'effect': 'Simple Action, spend Void Point and one spell slot: choose keyword, gain +4k1 to all Spell Casting Rolls with that keyword for the encounter.'}]},
    {'name': 'Dragon Clan Overseer', 'clan': 'Dragon', 'category': 'alternate', 'keywords': [], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Rank 2. Replaces: Kitsuki 2, Mirumoto Bushi 2, Taoist Swordsman 2, or Togashi Monk 2. Requires: Lore: Shadowlands 2, Lore: Theology 3. Oversee Spider Clan in the Colonies.', 'techniques': [{'rank': 0, 'name': "The Empress's Guiding Hand", 'effect': 'If Lore: Theology exceeds Courtier or Etiquette when dealing with lower Honor Rank individuals, gain bonus rolled dice equal to the difference on Contested Social rolls. Tainted opponents −2k0. Theology lesson (1 min + TN 25) grants +2k0 to resist Taint for 8 hours.'}]},
    {'name': "Dragon's Flame", 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Dragon Bushi 4. Requires: Kyujutsu 5. Individualistic archery tradition: defend the Dragon mountains.', 'techniques': [{'rank': 0, 'name': 'Rain of Death', 'effect': '+1k0 to attack rolls or +2k2 while using a bow.'}]},
    {'name': "Hojatsu's Legacy", 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Bushi', 'BoF'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': "Replaces: Mirumoto Bushi 4 or Mirumoto Taoist Swordsman 5. Requires: Iaijutsu 5. Disrupt opponent's rhythm rather than match speed: developed for the final Hojatsu-Kakita duel (both died).", 'techniques': [{'rank': 0, 'name': 'Strike When You Cannot', 'effect': 'During Assessment, spend Void Point as Free Action: Contested Kenjutsu/Fire roll: win and opponent cannot spend Void Points on their Focus roll.'}]},
    {'name': 'Kitsuki Debater', 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': "Replaces: Kitsuki Investigator 3. Requires: Courtier 3, Etiquette (Conversation) 5. Destroy opponent's court logic point by point: strip away their mask of courtesy.", 'techniques': [{'rank': 0, 'name': 'The Ebb and Flow of Deception', 'effect': 'Etiquette/Awareness (TN 20 + optional Raises): switch topic to something uncomfortable. Opponent rolls Sincerity/Awareness (TN 20 + 5 per Raise called) or suffers −1k1 to their next Social roll against you.'}]},
