    {'name': 'Mirumoto Mountaineer', 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Bushi', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Mirumoto Bushi 2. Requires: Athletics (Climbing) 3. Hardened by treacherous Dragon terrain.', 'techniques': [{'rank': 0, 'name': 'Heart of the Mountains', 'effect': 'When surprised (failed Investigation/Perception), immediately roll Athletics/Agility: success = not surprised. Add half Athletics Ranks (rounded up) to all ranged attack rolls.'}]},
    {'name': 'Mirumoto Sentinel', 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Mirumoto Bushi 4 or Taoist Swordsman 3. Requires: Way of the Land Advantage. Secure large sections of Dragon mountain territory: intimate knowledge of every province.', 'techniques': [{'rank': 0, 'name': 'Master the Land', 'effect': 'In provinces with Way of the Land, choose 3 Bugei Skills gaining +1k0. At start of skirmish, Contested Void Roll vs one opponent: their Water Ring counts as one lower for Move Action distances.'}]},
    {'name': 'Tamori Warrior Priest', 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Shugenja', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Tamori Shugenja 4. Requires: 1 weapon Skill at Rank 3. Martial training equally important as kami connection.', 'techniques': [{'rank': 0, 'name': 'Strength of the Soul', 'effect': 'Expend spell slot as Free Action for +1k0 on any Bugei Skill roll (max = School Rank per Round). Simple Action attacks while wielding elemental weapon spells (Bo of Water, Tetsubo of Earth, Katana of Fire, Yari of Air).'}]},
    {'name': 'Tamori Weaponsmiths', 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Shugenja/Artisan'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Tamori Shugenja 2. Requires: Craft: Weaponsmithing 3, one weapon-creating spell. Marry blade design with Earth power.', 'techniques': [{'rank': 0, 'name': 'Soul of the Stone', 'effect': 'On successful weapon Craft roll, expend all Void Points to instill Free Raises equal to Earth Ring: usable on any roll with the blade, refresh after 30 days. Max weapons equal to Earth Rank may exist at one time.'}]},
    {'name': "The Dragon's Wind", 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Mirumoto Taoist Swordsman 3 or Mirumoto Bushi 4. Requires: Horsemanship 5, Kyujutsu (Dai-Kyu) 5. Grants steed and Dai-Kyu if not owned. Cavalry archers: arrive, volley, withdraw.', 'techniques': [{'rank': 0, 'name': 'Way of the Horse and Bow', 'effect': 'Steed treats Moderate terrain as Basic, Difficult as Moderate. Attack with bow as Simple Action while mounted.'}]},
    {'name': 'The Transcendent Brotherhood', 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Monk'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Rank 2. Replaces: Any Tattooed Order 2. Requires: Fire 3, Earth 3, Meditation 3. Excommunicated from Brotherhood of Shinsei: believe pain tempers toward enlightenment. Housed by Dragon.', 'techniques': [{'rank': 0, 'name': 'Apotheosis of Fire', 'effect': 'Once per day, 1 hour meditation, Meditation/Fire (TN 20): immune to normal fire for Fire Ring hours (still feel pain). 1 Raise: magical fire immunity. 2 Raises: all fire immunity. While burning and for 10 minutes after, +Fire Ring to all Awareness/Perception/Intelligence rolls.'}]},
    {'name': 'Togashi Defender', 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Monk'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Togashi Tattooed Order 3. Physical focus: hone body through martial arts. Protect villages, fight alongside Mirumoto.', 'techniques': [{'rank': 0, 'name': 'Power Within and Without', 'effect': 'While unarmored with no Kiho or Tattoos active, gain Reduction equal to 3 + Void Ring. Gain one additional Tattoo.'}]},
    {'name': 'Water Hammer Smith', 'clan': 'Dragon', 'category': 'alternate', 'keywords': ['Artisan'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': "Replaces: Any Dragon School at Rank 2. Requires: Any one Craft Skill at 3+. Masters of Water Hammer City's sacred forge. Anyone can gain apprenticeship.", 'techniques': [{'rank': 0, 'name': 'Child of the Water', 'effect': 'Spend Void Point (or Water spell slot if shugenja) to add double Water Ring to all Craft Skill rolls for rest of day. Only one use per day.'}]},
    {'name': 'Hantei Bushi (Owl)', 'clan': 'Imperial', 'category': 'basic', 'keywords': ['Bushi'], 'benefit': '+1 Agility', 'skills': 'Athletics, Defense, Etiquette, Kenjutsu, Kyujutsu, Lore: Nonhumans, any one High or Bugei Skill', 'honor': '6.5', 'outfit': 'Average Clothing, Light Armor, Daisho, Bow, any one weapon, Traveling Pack, 4 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Blessings of Heaven', 'effect': 'When facing a nonhuman opponent, add either your Earth Ring or Honor Rank (whichever is higher) to your Armor TN. +1k0 to all attack rolls with Samurai weapons.'}, {'rank': 2, 'name': 'Wrath of the Earth Dragon', 'effect': 'At the start of your Turn, spend a Void Point as a Free Action: your attacks this Round ignore all Reduction of nonhuman opponents.'}, {'rank': 3, 'name': 'Speed of the Air Dragon', 'effect': 'Attack as a Simple Action when wielding Samurai weapons or when attacking a nonhuman opponent.'}, {'rank': 4, 'name': 'Courage of the Thunder Dragon', 'effect': 'After striking an opponent, spend a Void Point as a Free Action to ignore any one of that opponent’s Techniques, armor effects, spells, special qualities, or creature abilities (except Invulnerability) that reduce or mitigate damage.'}, {'rank': 5, 'name': 'Judgment of the Celestial Dragon', 'effect': 'Once per skirmish, after hitting your opponent, spend four Void Points to automatically reduce that opponent to Down/Out/Dead (whichever applies first). Against nonhuman opponents, costs three Void Points instead. GM’s discretion whether this works against transcendent entities such as Fortunes; GM may optionally allow it against such foes if you voluntarily die to activate it.'}]},
    {'name': 'Miya Herald', 'clan': 'Imperial', 'category': 'basic', 'keywords': ['Courtier', 'CR'], 'benefit': '+1 Awareness', 'skills': 'Courtier (Rhetoric), Defense, Etiquette (Courtesy), Horsemanship, Lore: Heraldry, Sincerity, any 1 High or Bugei Skill', 'honor': '6.5', 'outfit': 'Sensible Clothing, Wakizashi, Calligraphy Set, Horse (Rokugani pony), 10 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Voice of the Emperor', 'effect': 'While inside the borders of the Empire, spend a Void Point to gain the Way of the Land Advantage for your current province until you next sleep. Any Rokugani who reveres the Emperor and knowingly attacks you automatically loses Honor points equal to twice your School Rank.'}, {'rank': 2, 'name': 'Eyes of the Emperor', 'effect': 'Add your Honor Rank to all Etiquette (Courtesy) Skill Rolls made to resist others’ attempts to influence you.'}, {'rank': 3, 'name': 'Hand of the Emperor', 'effect': 'At the start of a skirmish or during the Reactions Step of any later round, spend a Void Point as a Free Action to prevent any Rokugani who reveres the Emperor from being able to harm you before the next Reactions Step (non-damaging capture or restraint is still permitted). Only active while you are not participating in the skirmish or a duel.'}, {'rank': 4, 'name': 'Blessing of the Emperor', 'effect': 'School Rank times per session, take a Complex Action to forcefully demand an end to violence. Make a Contested Courtier (Rhetoric)/Awareness vs Etiquette (Courtesy)/Willpower roll against all honorable samurai (Honor 1.0+) who revere the Emperor within hearing. All who lose must cease all aggressive action and cannot attack or cast offensive spells until they take damage or you give permission. Lasts one minute. Affects both enemies and allies. Cannot be used against criminals, bandits, the Lost, or nonhumans.'}, {'rank': 5, 'name': 'Glory of the Emperor', 'effect': 'When rolling Courtier or Etiquette against a target with at least Honor 1.0, add +5k0 to the roll.'}]},
    {'name': 'Otomo Courtier', 'clan': 'Imperial', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Awareness', 'skills': 'Courtier (Manipulation), Defense, Etiquette, Intimidation (Control), Investigation, Sincerity, any 1 High Skill', 'honor': '5.5', 'outfit': 'Traditional Clothing, Wakizashi, Knife, Calligraphy Set, 10 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Voice of Heaven', 'effect': 'No Honor point loss for using Intimidation (Control). When in conversation with a clan member (Great or Minor), make a Contested Courtier (Manipulation)/Awareness vs Etiquette (Courtesy)/Awareness roll to provoke a disagreement or argument between them and someone from another clan or faction of your choice.'}, {'rank': 2, 'name': 'Destiny Has No Secrets', 'effect': 'Spend a Void Point and roll Courtier/Awareness (TN 25) to learn one piece of critically useful information from your information network (GM chooses the specific intelligence).'}, {'rank': 3, 'name': 'My Master’s Voice (Obiesaseru)', 'effect': 'Complex Action: shout an appropriate Imperial command. Make a Contested Intimidation (Control)/Willpower vs Etiquette (Courtesy)/Willpower roll against one honorable samurai (Honor 1.0+) who reveres the Emperor (sincere belief in acting honorably grants target a Free Raise). On success, on their next Turn the target may not move, attack, cast spells, or take any action that would directly obstruct or threaten you or your immediate allies. Cannot be used against criminals, bandits, the Lost, or nonhumans.'}, {'rank': 4, 'name': 'The Emperor’s Protection', 'effect': 'When in an argument or debate, spend a Void Point and make a Contested Courtier (Manipulation)/Awareness vs Etiquette (Courtesy)/Awareness roll. On success, your opponent must either agree with your position or immediately lose 5 Honor points.'}, {'rank': 5, 'name': 'The Virtues of Command', 'effect': '+5k0 on Contested Social Rolls against anyone who reveres Imperial authority.'}]},
    {'name': 'Otomo Diplomat (Owl)', 'clan': 'Imperial', 'category': 'basic', 'keywords': ['Courtier'], 'benefit': '+1 Awareness', 'skills': 'Calligraphy, Courtier, Etiquette (Courtesy), Intimidation, Lore: Nonhumans, Sincerity, any one High Skill', 'honor': '6.5', 'outfit': 'Court Robes, Fan, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Wisdom of the Owl', 'effect': '+1k0 to Etiquette rolls. During any social interaction with nonhumans, Free Action to roll Lore: Nonhumans/Intelligence (TN 20) to recall an important aspect of social interaction with that nonhuman type (GM chooses what is remembered, always useful to the situation).'}, {'rank': 2, 'name': 'Unity of the Realms', 'effect': 'When encountering a nonhuman in a non-hostile environment, roll Courtier/Awareness (TN 25). On success, the nonhuman treats you as an Ally with Devotion 2 for the remainder of the encounter (unless you actively threaten or harm it).'}, {'rank': 3, 'name': 'The Voice of Heaven', 'effect': 'When spending a Void Point on an Intimidation roll, gain +2k2 instead of normal +1k1. Against nonhuman opponents, gain +3k2 instead. No Honor point loss for using Intimidation in this manner.'}, {'rank': 4, 'name': 'Uphold the Peace', 'effect': 'At the start of a skirmish or on your Turn in any later Round, Complex Action: spend a Void Point and demand cessation of hostilities. Make a Contested Intimidation/Willpower roll against all within hearing (+3k0 bonus against nonhumans). Those who lose must cease all offensive action until attacked or until three Rounds pass. Cannot work against Shadowlands creatures or denizens of Jigoku or Tengoku. No Honor point loss for using Intimidation this way.'}, {'rank': 5, 'name': 'Hantei’s Mandate', 'effect': 'Gain an additional +3k0 to Intimidation rolls with the Rank 4 Technique (stacks with the +3k0 bonus against nonhumans).'}]},
    {'name': 'Seppun Guardsman', 'clan': 'Imperial', 'category': 'basic', 'keywords': ['Bushi', 'CR'], 'benefit': '+1 Perception', 'skills': 'Battle, Defense, Etiquette, Iaijutsu, Kenjutsu (Katana), Kyujutsu, any 1 High Skill', 'honor': '6.5', 'outfit': 'Light Armor, Sturdy Clothing, Daisho, any 1 Weapon, Traveling Pack, 10 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Never in Darkness', 'effect': 'When rolling to resist a Social Skill roll that could tempt or lead you away from your duty (Temptation, Intimidation, Courtier), roll additional unkept dice equal to your School Rank. +1k1 to Investigation rolls to detect an ambush or surprise attack.'}, {'rank': 2, 'name': 'The Clouds Part', 'effect': 'Spend a Void Point at the start of your Turn to add your Honor Rank to the total of all attack and damage rolls until your next Turn.'}, {'rank': 3, 'name': 'Sun’s Light Reveals', 'effect': 'Spend a Void Point as a Free Action and roll Investigation (Notice)/Perception (TN 25). On success, immediately see through all disguises and illusions around you whether normal or magical. In the presence of the Emperor, immediate Imperial family, or a major Imperial Official, no Void Point is required. Once a specific disguise or illusion is pierced, it no longer affects you.'}, {'rank': 4, 'name': 'Speed of Heaven', 'effect': 'Attack as a Simple Action when using weapons with the Samurai keyword.'}, {'rank': 5, 'name': 'Heaven Never Falls', 'effect': 'When within 20’ of a person you are guarding, spend a Void Point to leap in front of a blow or spell targeting your charge: damage is automatically applied to you instead. If still standing (not Down or Out) afterward, immediately take one extra Simple Action for any purpose including an attack. Usable even while Blinded, Prone, Stunned, Dazed, Entangled, or at the Down Wound Rank (but not Grappled or Out).'}]},
    {'name': 'Seppun Shugenja', 'clan': 'Imperial', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Intelligence', 'skills': 'Calligraphy, Defense, Etiquette, Investigation (Notice), Meditation, Lore: Theology, any 1 High or Bugei Skill', 'honor': '6.5', 'outfit': 'Robes, Wakizashi, Bo, Scroll Satchel, Traveling Pack, 10 koku', 'affinity': 'Fire / Water | Starting Spells: Sense, Commune, Summon, 3 Fire, 2 Water, 1 Air', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'In Defense of the Throne', 'effect': 'Free Raise on any spell cast to protect the life, personal belongings, family, or reputation of the Emperor (provided doing so would not cause Honor point loss). Also applies to members of the Imperial families (but not yourself). Free Raise on any spells known only to the Imperial families.'}]},
    {'name': 'Seppun Shugenja (Owl)', 'clan': 'Imperial', 'category': 'basic', 'keywords': ['Shugenja'], 'benefit': '+1 Intelligence', 'skills': 'Calligraphy, Defense, Investigation, Lore: Nonhumans, Lore: Theology, Meditation, any one High Skill', 'honor': '6.5', 'outfit': 'Robes, Wakizashi, Bo Staff, Scroll Satchel, Traveling Pack, 4 koku', 'affinity': 'Fire / Water | Starting Spells: Sense, Commune, Summon, 3 Fire, 2 Air, 1 Earth', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'In Defense of Ningen-Do', 'effect': 'Free Raise on any spell targeting a nonhuman. When casting a damaging spell, expend an additional spell slot (same Element or Void) to have the spell ignore Reduction equal to twice your Void Rank. Against nonhuman targets, this also ignores all damage mitigation from creature abilities (except Invulnerability).'}]},
    {'name': 'Imperial Scion', 'clan': 'Imperial', 'category': 'advanced', 'keywords': ['Courtier', 'EE'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Awe of the Throne', 'effect': 'When called upon to make a Skill Roll or to use Glory or Honor Rank, spend a Void Point to substitute your Status Rank instead.'}, {'rank': 2, 'name': 'The Strength of the Throne', 'effect': 'After conversing with an opponent of lower Status Rank for a few minutes, force a Contested Courtier/Etiquette roll. On success, reduce their Status points by up to twice your Insight Rank.'}, {'rank': 3, 'name': 'The Terror of the Throne', 'effect': 'While conversing with an opponent of equal or lower Status Rank, force a Contested Void Roll. On success, permanently inflict any one Social Disadvantage on the opponent. Alternatively, force the opponent to become ronin (usable once every six months; costs you 5 points each of Glory, Honor, and Status).'}]},
    {'name': 'Tsudao’s Legion', 'clan': 'Imperial', 'category': 'advanced', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'All Things Through Honor', 'effect': 'When making a Skill Roll with a High or Bugei Skill in which you have at least 1 Rank, spend a Void Point to make that roll as though your Skill Rank equals your Honor Rank.'}, {'rank': 2, 'name': 'Wisdom of the Sensei', 'effect': 'When rolling on the Mass Battle Table, add or subtract your Void Ring from the total as desired. Select one Maneuver: whenever you attempt that Maneuver, gain one Free Raise toward success.'}, {'rank': 3, 'name': 'Empowered By Her Name', 'effect': 'If your Honor Rank exceeds your opponent’s Honor Rank, make one additional melee attack as a Free Action once per Round against that opponent.'}]},
    {'name': 'Imperial Influencer', 'clan': 'Imperial', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Otomo Courtier 3. Requires: Awareness 4, Etiquette 5, Sincerity 5. Must have Status 4.0+.', 'techniques': [{'rank': 0, 'name': 'Follow My Lead', 'effect': 'At any courtly event you are hosting, roll Courtier (Manipulation)/Awareness (TN 30) to set the dominant tone of the event (positive or negative, with a specific flavor). Anyone making a Social Skill Roll acting against the tone must call two Raises to no effect: failing due solely to those Raises constitutes a Minor Breach of Etiquette. Anyone acting in concert with the tone gains +2k0. If not the host, your roll becomes Contested against the host. Other guests may oppose you with Contested Courtier (Manipulation) rolls: the character with higher Status gains +1k0 per Status Rank of difference. Effects last until the end of the event.'}]},
    {'name': 'Imperial Observer', 'clan': 'Imperial', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Otomo Courtier 4, Miya Herald 4 (optionally any Courtier 4 with GM approval). Requires: Battle 4 or Lore: War 4, Sincerity 4, Status Rank 3.0+.', 'techniques': [{'rank': 0, 'name': 'Pierce the Fog of War', 'effect': 'When reporting on the events or conduct of a war, you are considered to have the Sacrosanct Advantage. Make a Sincerity/Awareness roll (TN = 5 × the commander’s Glory Rank) to praise or damn a commander on either side: on success, increase or decrease their Glory by 1 Rank. Raise to inflict or remove Infamy at a rate of half a Rank plus an additional half-Rank per Raise. No individual may be affected by this Technique more than once per battle reported.'}]},
    {'name': 'Otomo Bureaucrat', 'clan': 'Imperial', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Otomo Courtier 3. Requires: Etiquette (Bureaucracy) 5.', 'techniques': [{'rank': 0, 'name': 'Imperial Scrutiny', 'effect': 'Any time another samurai is trying to accomplish something in the courts, employ the intricacies of the Imperial bureaucracy to delay him. This takes up to several hours and is represented by a Contested Etiquette (Bureaucracy)/Willpower roll (spending a Void Point grants +2k2 instead of +1k1). On success, the samurai cannot make any progress toward his goal for the next two weeks regardless of what he does.'}]},
    {'name': 'Satoshi’s Legacy', 'clan': 'Imperial', 'category': 'alternate', 'keywords': ['Bushi', 'SE'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Miya Herald 4. Requires: Kenjutsu 5.', 'techniques': [{'rank': 0, 'name': 'Fire and Ice', 'effect': 'Make attacks as Simple Actions when in the Full Attack Stance.'}]},
    {'name': 'Seppun Astrologers', 'clan': 'Imperial', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Seppun Shugenja 4. Requires: Divination (Astrology) 4, Lore: Omens 5.', 'techniques': [{'rank': 0, 'name': 'Wisdom of the Heavens', 'effect': 'Once per month, clarify a person’s place in the tapestry of fate and confer one Spiritual Advantage or Spiritual Disadvantage on them (ritual only, cannot be used in a skirmish). Effect lasts one month or until you use this Technique on a different person. Conferring a Disadvantage requires a successful Contested Void Roll against the target.'}]},
    {'name': 'Seppun Hidden Guard', 'clan': 'Imperial', 'category': 'alternate', 'keywords': ['Shugenja', 'SE'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Seppun Shugenja 3. Requires: Must be chosen for service in the Hidden Guard.', 'techniques': [{'rank': 0, 'name': 'Harmony in All', 'effect': 'Free Raise on all spells with the Wards or Defense properties.'}]},
    {'name': 'The Rising Sun', 'clan': 'Imperial', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Seppun Guardsman 5 (with GM’s permission, any Bushi Basic School 5 if enrolled in the Imperial Legions). Requires: Strength 4, Horsemanship 5, Spears 5. Grants a steed if not already possessed.', 'techniques': [{'rank': 0, 'name': 'The Storm of Heaven’s Wrath', 'effect': 'While mounted and in Attack Stance, add your Honor Rank to Armor TN. Spend a Void Point to add half your Honor Rank (rounded up) in kept dice to your attack roll.'}]},
    {'name': 'Akodo Bushi', 'clan': 'Lion', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Perception', 'skills': 'Battle (Mass Combat), Defense, Kenjutsu, Kyujutsu, Lore: History, Sincerity, any one Bugei or High Skill', 'honor': '6.5', 'outfit': 'Light Armor, Sturdy Clothing, Daisho, any 1 weapon, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Way of the Lion', 'effect': 'Choose per attack: ignore the portion of the opponent’s Armor TN derived from Armor (Reduction still applies), or gain a Free Raise. Also gain +1k0 to all attack roll totals on your first melee attack against an opponent in a skirmish, or against any opponent who has declared a Raise on an attack against you since your last Turn (only once regardless of how many Raises they called).'}, {'rank': 2, 'name': 'Strength of Purity', 'effect': 'Once per Turn during a skirmish, add your Honor Rank to the total of any single roll. Cannot be used on damage rolls or while in Center Stance.'}, {'rank': 3, 'name': 'Strength of My Ancestors', 'effect': 'Attack as a Simple Action instead of a Complex Action with Samurai keyword weapons.'}, {'rank': 4, 'name': 'Triumph Before Battle', 'effect': 'Once per skirmish, designate an opponent during the Reactions Stage. During the following Round you may ignore all Armor TN bonuses that opponent gains from their Stance.'}, {'rank': 5, 'name': 'Akodo’s Final Lesson', 'effect': 'When making Raises on any Bugei Skill Roll, if you meet or exceed the original TN but fail to meet the Raised TN, you still succeed: without the benefits of the Raises.'}]},
    {'name': 'Ikoma Bard', 'clan': 'Lion', 'category': 'basic', 'keywords': ['Courtier', 'CR'], 'benefit': '+1 Intelligence', 'skills': 'Courtier, Etiquette, Lore: History (Lion Clan), Perform: Storytelling, Sincerity (Honesty), any one High Skill, any one Bugei Skill', 'honor': '6.5', 'outfit': 'Traditional Clothing, Wakizashi, Knife, Calligraphy Set, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Herald of Glory', 'effect': 'Gain Precise Memory Advantage at no XP cost (refunded if already possessed). May use Perform: Storytelling to publicly brag on behalf of another: rolling Perform: Storytelling/Awareness (TN 20) awards that person Glory points equal to your School Rank, up to School Rank times per person per month.'}, {'rank': 2, 'name': 'The Heart of the Lion', 'effect': 'No Honor or Glory point loss for displaying emotion in public on behalf of another Lion or an honorable cause greater than yourself. Anyone attempting to sway you with Intimidation or Temptation adds +5 to their TN per School Rank.'}, {'rank': 3, 'name': 'The Voice of the Ancestors', 'effect': 'Prior to a battle or skirmish, inspire allies by speaking for a few minutes and rolling Perform: Oratory/Awareness (TN 15 + 5 per person inspired; non-Lion add +5 each). Each inspired target may add their Honor Rank to one Skill Roll total during that battle. Unused by battle’s end, it is lost.'}, {'rank': 4, 'name': 'The Strength of Tradition', 'effect': 'School Rank times per session, spend a Simple Action and roll Perform: Storytelling/Awareness (TN 25). On success, the next time that ally fails a roll that day, they may reroll it, adding your Honor Rank in unkept dice. If they fail the reroll, you lose 2 Honor points.'}, {'rank': 5, 'name': 'Every Lion is Your Brother', 'effect': 'Five times per session, when making a Contested Social Roll, cite historical precedent and add unkept dice equal to your Perform: Storytelling Rank. GM has final say on appropriateness.'}]},
    {'name': 'Ikoma Lion’s Shadow', 'clan': 'Lion', 'category': 'basic', 'keywords': ['Bushi', 'EE'], 'benefit': '+1 Awareness', 'skills': 'Courtier, Etiquette, Kenjutsu, Investigation (Notice), Sincerity, Stealth, any 1 High or Low Skill', 'honor': '3.5', 'outfit': 'Traditional Clothing, Daisho, any 1 weapon, Calligraphy Set, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'No Boundaries', 'effect': 'No Honor point loss for using Low Skills when used directly for the goals or glory of the Lion Clan (GM’s judgement). Free Action: target a number of opponents equal to School Rank; gain +1k0 to all attack rolls and Contested Rolls against those opponents. Activatable School Rank times per day; lasts until end of day.'}, {'rank': 2, 'name': 'The Lion Cannot Fail', 'effect': '+1k0 to all Skill Rolls using School Skills.'}, {'rank': 3, 'name': 'The Spirit of Ikoma', 'effect': 'Once per Round, lose 3 Honor points as a Free Action to gain +2k1 to attack, damage, and Contested Social Skill Rolls until end of Round.'}, {'rank': 4, 'name': 'The Quiet Lion’s Claws', 'effect': 'Make melee weapon attacks as a Simple Action instead of a Complex Action.'}, {'rank': 5, 'name': 'Ferocious Determination', 'effect': 'Spend a Void Point as a Free Action: Contested Courtier/Awareness vs opponent’s Etiquette (Courtesy)/Awareness. On success, opponent subtracts a penalty equal to your Awareness plus their own Honor Rank from all attack and Contested Social Skill Rolls against you for hours equal to your School Rank. Does not work against creatures with no Honor Rank.'}]},
    {'name': 'Kitsu Shugenja', 'clan': 'Lion', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Perception', 'skills': 'Battle, Calligraphy (Cipher), Etiquette, Lore: History, Lore: Theology, Spellcraft, any one High or Bugei Skill', 'honor': '6.5', 'outfit': 'Robes, Wakizashi, Knife, Scroll Satchel, Traveling Pack, 5 koku', 'affinity': 'Water / Fire | Starting Spells: Sense, Commune, Summon, 3 Water, 2 Air, 1 Earth', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'Eyes of the Ancestors', 'effect': 'Make a Spell Casting Roll (as a Water spell) against a target’s Willpower ×5. On success, learn all Spiritual Advantages or Disadvantages that individual possesses. Spend a Void Point to negate any one Spiritual Advantage an opponent possesses for minutes equal to School Rank. Free Raise on any spell with the Battle keyword.'}]},
    {'name': 'Lion Elite Spearmen', 'clan': 'Lion', 'category': 'basic', 'keywords': ['Bushi', 'NP'], 'benefit': '+1 Reflexes', 'skills': 'Battle, Defense, Kenjutsu, Lore: History, Polearms, Spears (Magari-Yari), any one Bugei or High Skill', 'honor': '5.5', 'outfit': 'Normal Clothing, Daisho, bundle of ten nage-yari, magari-yari, any one other spear or polearm, Light or Ashigaru Armor, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Way of Magari-Yarijutsu', 'effect': '+1k0 to all Spear and Polearm Skill Rolls. When wielding a spear or polearm in Center, Defense, or Full Defense Stance, gain Reduction equal to half your Skill Rank in the weapon.'}, {'rank': 2, 'name': 'Strike Like the Lion', 'effect': 'When wielding a spear or polearm (melee or ranged), ignore enemy Reduction equal to half your current Honor Rank (rounded up).'}, {'rank': 3, 'name': 'Strike Through the Eagle', 'effect': 'Ready/draw a nage-yari as a Free Action any number of times per Round. Ranged hand-hurled attacks with nage-yari are Simple Actions.'}, {'rank': 4, 'name': 'Strike Like the Wind', 'effect': 'Make melee attacks as a Simple Action when wielding a spear or polearm.'}, {'rank': 5, 'name': 'Strike With the Soul', 'effect': 'Extra Attack Maneuver costs only 3 Raises with spear or polearm. When hurling spears as missile weapons, make one attack as a Free Action.'}]},
    {'name': 'Matsu Beastmaster', 'clan': 'Lion', 'category': 'basic', 'keywords': ['Bushi'], 'benefit': '+1 Agility', 'skills': 'Animal Handling 2, Battle, Defense, Iaijutsu, Kenjutsu, any 1 Bugei Skill', 'honor': '5.5', 'outfit': 'Light Armor, Sturdy Clothing, Daisho, any 1 weapon, Traveling Pack, 4 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'One with the Pride', 'effect': 'Bond with one lion warcat: it accompanies you everywhere and follows basic commands without compulsion. No lion will attack you without being compelled. Direct one warcat to Attack as a Complex Action. Any warcat not attacking uses Guard to protect you.'}, {'rank': 2, 'name': 'Heart of the Beast', 'effect': 'A second lion joins your pride. You and all companion lions gain Swift 2. All lions gain an additional Wound Rank (final progression: 36: +15, 60: Dead).'}, {'rank': 3, 'name': 'The Ferocity Within', 'effect': 'When wielding a katana, wakizashi, magari-yari, nage-yari, any knife, or fighting unarmed, make melee attacks as a Simple Action. Direct one warcat to Attack as a Simple Action.'}, {'rank': 4, 'name': 'All as One', 'effect': 'Pride members make two claw attacks per Round. You and all pride members gain +2k1 to damage rolls when fighting alongside one another. When you direct a warcat to Attack, it may also make a Simple Move Action that Round.'}, {'rank': 5, 'name': 'With the Soul of a Lion', 'effect': 'A third lion joins your pride. All warcats gain +10 Armor TN, +2 Reduction, and +2 Fear.'}]},
    {'name': 'Matsu Berserker', 'clan': 'Lion', 'category': 'basic', 'keywords': ['Bushi', 'CR'], 'benefit': '+1 Strength', 'skills': 'Battle, Jiujutsu, Kenjutsu (Katana), Kyujutsu, Lore: History, any two Bugei Skills', 'honor': '6.5', 'outfit': 'Light or Heavy Armor, Sturdy Clothing, Daisho, Heavy Weapon or Polearm, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Lion’s Roar', 'effect': 'Add Honor Rank to all damage rolls. When assuming Full Attack Stance, move an additional 5 feet per Turn beyond the Stance bonus (cannot exceed maximum movement).'}, {'rank': 2, 'name': 'Matsu’s Fury', 'effect': 'When assuming Full Attack Stance, choose an opponent within 30’. If you hit them this Turn, they are frozen with fear and cannot take Move Actions. Each Reactions Stage, the affected opponent may roll Willpower (TN = damage dealt from your latest attack, ignoring Wound Rank penalties) to negate. Immune-to-Fear targets cannot be affected.'}, {'rank': 3, 'name': 'The Lion’s Charge', 'effect': 'Make melee attacks as a Simple Action instead of a Complex Action.'}, {'rank': 4, 'name': 'Matsu’s Courage', 'effect': 'Ignore TN penalties from Wound Levels equal to your Honor Rank: or twice your Honor Rank while in Full Attack Stance.'}, {'rank': 5, 'name': 'The Lion’s Victory', 'effect': 'Once per encounter, after rolling damage, spend a Void Point as a Free Action. All kept dice explode: reroll each and add results to your damage total.'}]},
    {'name': 'Akodo Tactical Master', 'clan': 'Lion', 'category': 'advanced', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Eyes of the General', 'effect': 'Reroll any one die each Battle Turn of Mass Combat. Also reroll any one die during an attack roll in which you called at least one Raise.'}, {'rank': 2, 'name': 'Malleable as the Sea', 'effect': 'Spend a Void Point to choose any one Heroic Opportunity from the corebook to perform during a Mass Battle Turn (subject to GM approval).'}, {'rank': 3, 'name': 'The Soul of the Army', 'effect': 'Spend a Void Point to gain +5k2 on any Battle Skill Roll (instead of the normal +1k1), or +2k2 on any Bugei Skill Roll (instead of +1k1).'}]},
    {'name': 'Kitsu Sodan-Senzo', 'clan': 'Lion', 'category': 'advanced', 'keywords': ['Shugenja', 'IH'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Senses of the Kitsu', 'effect': 'Detect spirit portals within School Rank ×10 miles (GM rolls Spellcraft/Perception TN 25 secretly; automatic if within School Rank miles). Previous School Rank increases by 1 for casting purposes.'}, {'rank': 2, 'name': 'Hand of the Kitsu', 'effect': 'Unarmed damage increases by +0k1 (spiritual talons). Roll Meditation (TN 30) to project your soul into Meido or Yomi to interact with ancestral spirits using Social Skill Rolls as normal.'}, {'rank': 3, 'name': 'Soul of the Kitsu', 'effect': 'When projecting into spirit realms, bring one other person if they also succeed at the Meditation roll. Passenger sees and hears everything but cannot speak. Ancestral spirits can sense the passenger. Gain one additional rank in your previous School for casting purposes.'}]},
    {'name': 'The Lion’s Pride', 'clan': 'Lion', 'category': 'advanced', 'keywords': ['Bushi', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Fury of Matsu', 'effect': 'Add +10 to Armor TN while in Full Attack Stance.'}, {'rank': 2, 'name': 'Paragon of Honor', 'effect': 'Opponents with lower Honor Rank within 30’ may not reroll 10s. An opponent may ignore this effect for the encounter by spending 2 Void Points during the Reactions Stage of any Combat Round.'}, {'rank': 3, 'name': 'Matsu’s Technique', 'effect': 'When an opponent declares a melee attack against you and you have not yet taken your Turn this Round, spend a Void Point as a Free Action to immediately make a Simple Action attack: resolving before their attack. You may only perform one Simple Action on your Turn this Round. Usable in Full Attack Stance.'}]},
    {'name': 'Akodo Kensai', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Lion Bushi 4. Requires: Iaijutsu 4, Kenjutsu 5, Prodigy Advantage (may waive Prodigy by increasing all other requirements by 1).', 'techniques': [{'rank': 0, 'name': 'The Heart of the Sword', 'effect': 'While using a sword in Attack Stance, increase Armor TN by Honor Rank against the first melee attack of each Combat Round. Once per skirmish, activate a Kata as a Free Action.'}]},
    {'name': 'Akodo Siege Strategist', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Akodo Bushi 4 or Akodo Tactical Master 2. Requires: Battle (Mass Battle) 6, Engineering (Siege) 4.', 'techniques': [{'rank': 0, 'name': 'Broken by Tactics', 'effect': 'When on the attacking side of a siege, always receive a Heroic Opportunity when rolling on the Mass Battle Table regardless of the normal result. Opposing structures suffer a 50% Reduction penalty (applied after any defensive bonuses).'}]},
    {'name': 'Bishamon’s Chosen', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Shugenja', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Kitsu Shugenja 3. Requires: Battle 3.', 'techniques': [{'rank': 0, 'name': 'Scion of Strength', 'effect': 'Expend a spell slot as a Free Action to gain +1k0 to any Strength-based roll including melee damage, or +1k0 to the Spell Casting Roll of any spell with the Battle descriptor.'}]},
    {'name': 'De Bellis Legionnaire', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Akodo Bushi 4, Matsu Berserker 4. Requires: Battle 3, Lore: Gaijin (Yodotai) 1.', 'techniques': [{'rank': 0, 'name': 'I Stand with My Brothers', 'effect': 'At the start of a skirmish, roll Battle/Awareness (TN 15) as a Free Action. On success, gain unkept bonus dice equal to the number of allies in your group plus one per Raise (max twice School Rank total; max School Rank on any one roll). Use on attack or damage rolls, or on Defense Skill Rolls when declaring Full Defense. Unused dice are lost at end of skirmish.'}]},
    {'name': 'Deathseeker', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Lion Bushi School 1. Requires: Honor Rank 5, Dishonored Disadvantage.', 'techniques': [{'rank': 0, 'name': 'Honor of the Lion', 'effect': 'Gain the Benefit, Skills, Honor, and Outfit of a Rank 1 Lion bushi (any Lion school). Add Honor Rank to the total of one damage roll per Turn; if you do, Armor TN is reduced by 5 until the next Round’s Reactions Stage. +1k0 to attack rolls while in Full Attack Stance.'}]},
    {'name': 'Disciples of the River', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Kitsu Shugenja 3. Requires: Way of the Land Advantage for an area with a river.', 'techniques': [{'rank': 0, 'name': 'Servant of the River', 'effect': 'When casting a Water spell while standing within one hundred feet of a naturally occurring river, gain one Free Raise on that spell.'}]},
    {'name': 'Ikoma Historians', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Ikoma Bard 3, Ikoma Lion’s Shadow 3. Requires: Lore: History 5.', 'techniques': [{'rank': 0, 'name': 'The Past and the Present', 'effect': 'Acquire the Forbidden Knowledge (Empire’s True History) Advantage. Free Raise on all Calligraphy rolls. Roll Lore: History/Intelligence (TN 25) to accurately recount any incident witnessed or story heard, including details missed at the time.'}]},
    {'name': 'Ikoma Orator', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Ikoma Bard 3. Requires: Sincerity 4, Lore: Bushido 3, Perform: Oratory 4.', 'techniques': [{'rank': 0, 'name': 'The Voice of Bushido', 'effect': 'Give a speech of at least five minutes before a court audience. Targeting an ally: Perform: Oratory/Awareness (TN 30): on success, grant that ally one Paragon of Bushido Advantage for one week. Targeting an enemy: same roll if unopposed, or Contested Perform: Oratory/Awareness vs Sincerity/Awareness if they respond: on success, inflict one Failure of Bushido Disadvantage for one week (or deny the corresponding Paragon Advantage if held). Cannot affect the same person twice in one month.'}]},
    {'name': 'Ikoma Scrapper', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Akodo Bushi 4, Matsu Berserker 4, Ikoma Lion’s Shadow 4, Ikoma Bard 4. Requires: Strength 4, Jiujutsu 5.', 'techniques': [{'rank': 0, 'name': 'Every Scar Has a Name', 'effect': 'Attack as a Simple Action with unarmed strikes and improvised weapons (if not already possessed). Once per skirmish, when striking unarmed or with an improvised weapon, call two Raises to inflict a Fear effect on the target with Rank equal to your Insight Rank.'}]},
    {'name': 'Ikoma Warden', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Akodo Bushi 2 or Ikoma Lion’s Shadow 2. Requires: Horsemanship 3.', 'techniques': [{'rank': 0, 'name': 'To Race the Wind', 'effect': 'While Mounted, +1k0 to all Bugei Skill Rolls. When spending a Void Point on a Horsemanship or Investigation Skill Roll, gain +2k2 instead of +1k1.'}]},
    {'name': 'Kitsu Spirit Legion', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Kitsu Shugenja 4. Requires: Must be born with the spiritual gifts required: a character development and roleplay constraint discussed between player and GM.', 'techniques': [{'rank': 0, 'name': 'The Legions of the Dead', 'effect': 'Complex Action: expend 2 spell slots of one chosen Element and spend a Void Point. A spirit warrior appears with the Spirit trait; all Rings at 2 except the sacrificed Element’s Ring (which starts at 3). The spirit has Kenjutsu 3, Defense 2, spectral daisho and light armor. Remains in the mortal realm for hours equal to your Kitsu Shugenja School Rank or until dismissed.'}]},
    {'name': 'Lion Paragon', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Lion Bushi 3. Requires: Void Ring 4, Kenjutsu 5, Honor Rank 7.', 'techniques': [{'rank': 0, 'name': 'Pure and Dedicated', 'effect': 'Make melee attacks as a Simple Action, but only one attack per Turn (no Extra Attack Maneuver). Once per skirmish, spend a Void Point as a Free Action: your Honor Rank counts as double for all other School Techniques for the remainder of the encounter. Does not stack with other Honor Rank modifiers; use the highest.'}]},
    {'name': 'Lion Scout', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Lion Bushi 2. Requires: Battle 2, Hunting 3.', 'techniques': [{'rank': 0, 'name': 'Shadow Unseen', 'effect': 'Move at a normal rate while using the Stealth Skill. +1k0 to Stealth Skill Rolls and all Agility-based Bugei Skills.'}]},
    {'name': 'Lion Tactician (Ikoma Tactician)', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Lion Bushi 4, Ikoma Bard 4. Requires: Battle 4, War Fan 4, must be at least Gunso in rank.', 'techniques': [{'rank': 0, 'name': 'The Commander’s Fan', 'effect': '+1k1 to Battle (Mass Battle) rolls when your war-fan aids in conveying orders (GM’s discretion). While carrying a war-fan, add half your War Fans Skill Rank (rounded up) to Armor TN. In Defense or Full Defense Stance, or when carrying only a war-fan, add full Skill Rank instead. Does not stack; two war-fans do not double the bonus.'}]},
    {'name': 'Lioness Legion', 'clan': 'Lion', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Matsu Berserker 2, Akodo Bushi 2, or Matsu Beastmaster 2. Requires: Athletics 3.', 'techniques': [{'rank': 0, 'name': 'Charge of the Pride', 'effect': 'While in Full Attack Stance, all movement during the Round gains an additional 5 feet (once per Round only). As a Complex Move Action, move Water Ring × 25 feet.'}]},
    {'name': 'Kitsune Shugenja: Fox Clan / later Mantis Clan', 'clan': 'Mantis', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Stamina', 'skills': 'Calligraphy, Defense, Hunting, Medicine (Herbalism), Meditation, Spellcraft, any one High or Bugei Skill', 'honor': '4.5', 'outfit': 'Robes, Wakizashi, Knife, Scroll Satchel, Traveling Pack, 3 koku', 'affinity': 'Earth / Air | Starting Spells: Sense, Commune, Summon, 3 Earth, 2 Water, 1 Fire', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'Essence of Chikushudo', 'effect': 'May use the Sense, Commune, and Summon basic spells to affect animal spirits of Chikushudo as well as kami (Summon produces a single animal spirit rather than elemental material). Free Raise on any non-damaging spell cast on an animal.'}]},
    {'name': 'Mantis Brawler', 'clan': 'Mantis', 'category': 'basic', 'keywords': ['Bushi'], 'benefit': '+1 Agility', 'skills': 'Athletics, Commerce, Intimidation, Jiujutsu, Knives, Sailing, any 1 Weapon Skill', 'honor': '3.5', 'outfit': 'Rugged Clothing, any 2 weapons, Kama, Tanto, Traveling Pack, 4 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Way of Drunken Fists', 'effect': 'While Prone, suffer no penalties to Armor TN or attacks with Small weapons or unarmed (still gain Prone bonus vs ranged). +1k0 to rolls to take control of Grapples and to damage rolls with unarmed strikes, improvised weapons, and Small weapons.'}, {'rank': 2, 'name': 'Drunk Loses His Sandal', 'effect': 'After a successful Feint, reduce the extra damage by 5 to instead add +5 to Armor TN until the start of the next Turn (+10 if you were Prone when performing the Feint). Immediately after any enemy attack resolves against you, take a Free Action to become Prone.'}, {'rank': 3, 'name': 'Drunk Never Falls', 'effect': 'Do not suffer penalties for Fatigued, Dazed, or intoxication. If Stunned, may still take one Simple Action per Round.'}, {'rank': 4, 'name': 'Two Drunks Dance', 'effect': 'Attack as a Simple Action when fighting unarmed, with an improvised weapon, or with a Small weapon.'}, {'rank': 5, 'name': 'Drunk Pounds a Door', 'effect': 'Spend a Void Point on a melee attack to gain +4k1 to both the attack roll and the damage roll. If Prone, the bonus is +4k2 instead.'}]},
    {'name': 'Moshi Shugenja: Centipede Clan / later Mantis Clan', 'clan': 'Mantis', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Awareness', 'skills': 'Calligraphy (Cipher), Divination, Lore: Theology, Meditation, Spellcraft, any two High or Bugei Skills', 'honor': '4.5', 'outfit': 'Robes, Wakizashi, Knife, Scroll Satchel, Traveling Pack, 10 koku', 'affinity': 'Air / Earth | Starting Spells: Sense, Commune, Summon, 3 Air, 3 Fire', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'Favor of the Sun', 'effect': 'During the day, gain an additional Affinity for Fire spells (lost at night). Free Raise on any spell with the Thunder keyword.'}]},
    {'name': 'Tsuruchi Archer: Wasp Clan / later Mantis Clan', 'clan': 'Mantis', 'category': 'basic', 'keywords': ['Bushi', 'CR'], 'benefit': '+1 Reflexes', 'skills': 'Athletics, Defense, Hunting, Investigation, Kyujutsu (Yumi) 2, any one Bugei or High Skill', 'honor': '3.5', 'outfit': 'Ashigaru or Light Armor, Sturdy Clothing, Bow and 20 Arrows, Wakizashi, Traveling Pack, 10 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Always Be Ready', 'effect': '+1k0 to all attack rolls using a bow. +3 to Initiative Score.'}, {'rank': 2, 'name': 'The Arrow Knows the Way', 'effect': 'One Free Raise usable only for the Called Shot Maneuver. +2k0 to all damage rolls while using a bow.'}, {'rank': 3, 'name': 'The Wasp’s Sting', 'effect': 'Attack as a Simple Action when using a bow.'}, {'rank': 4, 'name': 'Flight of No-Mind', 'effect': 'Once per skirmish, spend a Void Point as a Complex Action to shoot an arrow that ignores all armor effects and penalties from Wound Ranks or visibility. May make Raises but not the Extra Attack Maneuver. Cannot target beyond normal range.'}, {'rank': 5, 'name': 'Tsuruchi’s Eye', 'effect': 'Make a ranged attack as a Complex Action to gain +4k1 to both attack and damage rolls. Cannot be used in conjunction with Flight of No-Mind.'}]},
    {'name': 'Tsuruchi Bounty Hunter: Wasp Clan / later Mantis Clan', 'clan': 'Mantis', 'category': 'basic', 'keywords': ['Bushi'], 'benefit': '+1 Agility', 'skills': 'Athletics, Hunting (Tracking), Intimidation, Investigation, Kenjutsu, Kyujutsu, Lore: Underworld', 'honor': '4.5', 'outfit': 'Ashigaru or Light Armor, Sturdy Clothing, Daisho, Bow or Knife, Traveling Pack, 10 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'A Hunter’s Sense', 'effect': '+1k1 to Intimidation against lower-caste individuals you believe can help find your prey; +1k0 but applying to all Social Skill Rolls against samurai. When hunting a target, roll additional unkept dice equal to School Rank on any Hunting or Investigation Skill Rolls to track the quarry.'}, {'rank': 2, 'name': 'No Prey Escapes', 'effect': 'Spend a Void Point to automatically succeed at a Lore: Underworld roll to identify criminals in an area who can be pressed for information. Honor point loss for associating with such individuals applies as normal.'}, {'rank': 3, 'name': 'Justice of the Wasp', 'effect': 'Against an opponent declared guilty by Imperial or higher Mantis authority, the Disarm or Knockdown Maneuvers cost one Raise less than normal. Successfully executing either Maneuver automatically Dazes the opponent.'}, {'rank': 4, 'name': 'Twin Sting Strike', 'effect': 'Make ranged attacks as a Simple Action with a yumi. Against any target decreed guilty by Imperial or higher Mantis authority, also make melee attacks as a Simple Action with a katana or knife.'}, {'rank': 5, 'name': 'Eyes of the Wasp', 'effect': 'When identifying a samurai with a Lore: Heraldry roll, also learn their Honor Rank and all Social and Mental Disadvantages. Any opponent targetable by your Rank 3 Technique is now automatically Dazed when you successfully hit them, regardless of whether a Disarm or Knockdown Maneuver was used.'}]},
    {'name': 'Yoritomo Bushi', 'clan': 'Mantis', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Strength', 'skills': 'Commerce, Defense, Jiujutsu (Improvised Weapons), Kenjutsu, Knives (Kama), Sailing, any one Skill', 'honor': '3.5', 'outfit': 'Light Armor, Sturdy Clothing, Daisho, any 1 weapon (or pair of Knives), Traveling Pack, 10 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Way of the Mantis', 'effect': 'No penalties to movement or attacks for rough or uneven terrain. No Glory or Honor loss for using improvised weapons or Peasant keyword weapons in combat. No off-hand penalties for a Small or Medium Peasant keyword weapon. +1k0 to all attack rolls.'}, {'rank': 2, 'name': 'Voice of the Storm', 'effect': 'Every time you hit an opponent in melee, their Armor TN is reduced by 5 (applies only to your attacks, lasts 2 Rounds, cumulative up to School Rank times; duration resets with each application).'}, {'rank': 3, 'name': 'Strike of the Mantis', 'effect': 'Attack as a Simple Action with weapons with the Samurai or Peasant keyword.'}, {'rank': 4, 'name': 'The Rolling Wave', 'effect': 'If you move at least 5 feet, gain +10 to Armor TN until your next Turn. May sacrifice this bonus before rolling any attack to gain two Free Raises usable only for the Knockdown Maneuver.'}, {'rank': 5, 'name': 'Hand of Osano-Wo', 'effect': 'Spend a Void Point as a Free Action: keep additional damage dice equal to your Strength. Against Prone targets, also gain +0k2 to damage roll totals.'}]},
    {'name': 'Yoritomo Courtier', 'clan': 'Mantis', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Willpower', 'skills': 'Commerce (Appraisal), Courtier, Defense, Etiquette, Intimidation (Control), Sincerity, any one Merchant or Lore Skill', 'honor': '2.5', 'outfit': 'Extravagant Clothing, Wakizashi, any 1 weapon, Calligraphy Set, Traveling Pack, 10 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Duty Before Honor', 'effect': 'No Glory or Honor loss for using Commerce in public. No Honor point loss for using Intimidation (Control). Against ronin, bandits, gang members, mercenaries, pirates, and other lawless types, gain Free Raises equal to your School Rank on all Social Skill Rolls.'}, {'rank': 2, 'name': 'Storm Heart', 'effect': 'When using Intimidation (Control), your Willpower is considered one Rank higher. Against a samurai of lower Status Rank, two Ranks higher instead.'}, {'rank': 3, 'name': 'Command the Winds', 'effect': 'School Rank times per session, if you have failed a Sincerity Social Skill Roll, reroll it as an Intimidation (Control) Social Skill Roll instead. Must keep the Intimidation result.'}, {'rank': 4, 'name': 'Will of the Storm', 'effect': 'When initiating a conversation, make a Contested Intimidation (Control)/Willpower vs Etiquette (Courtesy)/Willpower roll. On success, the target cannot spend Void Points against you for the next hour and suffers −3k0 on all Social Rolls made against you. Cannot be used again until the effect expires.'}, {'rank': 5, 'name': 'Strength in All Things', 'effect': '+5k0 on any Intimidation roll, and on any roll to resist Intimidation, Temptation, or a Fear effect.'}]},
    {'name': 'Yoritomo Shugenja', 'clan': 'Mantis', 'category': 'basic', 'keywords': [], 'benefit': '+1 Perception', 'skills': 'Athletics, Calligraphy, Knives, Lore: Theology, Meditation, Sailing (Navigation), any 1 Skill', 'honor': '4.5', 'outfit': 'Robes, Wakizashi, any 1 weapon, Scroll Satchel, Traveling Pack, 10 koku', 'affinity': 'Water / Earth | Starting Spells: Sense, Commune, Summon, 3 Water, 2 Fire, 1 Air', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'Child of the Sea', 'effect': 'Expend one spell slot to alter wind conditions in your current location by one degree. Spending a Void Point instead shifts entire weather status one degree. Maximum combined spell slots and/or Void Points equal to School Rank per Round. Affects an area School Rank miles in all directions. Free Raise on all spells with the Thunder keyword.'}]},
    {'name': 'Kobune Captain', 'clan': 'Mantis', 'category': 'advanced', 'keywords': ['Bushi', 'EE'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Joy of Plunder', 'effect': 'Status Rank considered one higher when interacting with all Mantis Clan members and heimin merchants. Spending a Void Point on any Merchant Skill grants +2k2 instead of +1k1. Once per month, make a Commerce/Intelligence roll (TN 25) and gain koku equal to the amount by which your roll exceeds the TN.'}, {'rank': 2, 'name': 'Strength of the Mantis', 'effect': 'Gain 30 XP usable only to purchase the Servants Advantage (representing your crew). Budoka servants are instead considered Rank 1 Yoritomo Bushi. May spend 10 XP to gain a Rank 1 Moshi Shugenja navigator (Air 3 rather than all Rings at 2).'}, {'rank': 3, 'name': 'Master of the Seas', 'effect': 'Spend a Void Point on any Merchant Skill Roll (excluding Craft Skills) to replace the normal dice rolled with 10k10. +3k0 to all Bugei Skill Rolls made while aboard a water-borne vessel.'}]},
    {'name': 'Storm Riders', 'clan': 'Mantis', 'category': 'advanced', 'keywords': ['Shugenja', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Strength of Suitengu', 'effect': 'Shugenja School Rank considered one higher for casting Water spells. Spend a Void Point as a Complex Action to release a lightning bolt: one target within 10’ × Water Ring, dealing Air Ring kept damage dice. Expend additional spell slots for +1k0 damage per slot, up to your Storm Rider Rank.'}, {'rank': 2, 'name': 'The Raging Ocean', 'effect': 'Shugenja School Rank increases by one. Water Ring considered 2 Ranks higher for determining number of Water spells castable per day.'}, {'rank': 3, 'name': 'Child of Osano-Wo', 'effect': 'Shugenja School Rank considered one higher for casting Water spells. Spend a Void Point as a Free Action to gain immunity to all spells with the Thunder keyword for 3 Rounds (Mastery Level 3 and lower only).'}]},
    {'name': 'Acolyte of Thunder', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Yoritomo Shugenja 4. Requires: Fire 3, Void 4.', 'techniques': [{'rank': 0, 'name': 'Thunder’s Call', 'effect': 'Cast Fury of Osano-Wo as a Simple Action by sacrificing a spell slot of any Element. Raises for damage on that spell award +1k1 per Raise instead of +1k0.'}]},
    {'name': 'Children of Chikushodo: Fox/Kitsune', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Kitsune Shugenja 3. Requires: Hunting 3, Lore: Spirit Realms (Chikushudo) 2.', 'techniques': [{'rank': 0, 'name': 'Born of the Earth', 'effect': 'While sitting on bare earth, sacrifice two Earth spell slots and make a Meditation roll (TN 15). After ten minutes of meditation, fall into a trance and an animal erupts from the ground before your body. Your mind inhabits and controls this animal until you choose to end it, your real body is disturbed or harmed, or the animal form is killed. The animal form crumbles to dirt when the effect ends. Use the animal’s physical/mental Traits if they are higher than yours, otherwise use your own. Gain all creature abilities but cannot speak or cast spells while in animal form.'}]},
    {'name': 'Kitsune Artisan: Fox/Kitsune', 'clan': 'Mantis', 'category': 'alternate', 'keywords': [], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Kitsune Shugenja 2. Requires: Any one Artisan or Craft Skill at 3.', 'techniques': [{'rank': 0, 'name': 'The Beauty of the World', 'effect': 'When working with natural materials, expend an Earth spell slot to gain +1k0 on any Artisan or Craft Skill Roll. May expend up to School Rank spell slots this way; may be used in conjunction with Void Points.'}]},
    {'name': 'Kitsune Ranger: Fox/Kitsune', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Mantis Bushi 2. Requires: Hunting 3. Special: Prior to joining the Mantis, may be taken as a Rank 2 Path by any bushi-trained Kitsune or as a Rank 2 Ronin Technique for any ronin with a Kitsune Ally Advantage.', 'techniques': [{'rank': 0, 'name': 'One With the Wild', 'effect': 'Free Raise on all Hunting Skill Rolls and on Stealth Skill Rolls in rural environments. +2k0 on any Contested Roll involving detection (whether avoiding detection or detecting a hidden opponent).'}]},
    {'name': 'Mantis Navigator', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Shugenja', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Mantis Shugenja School 3. Requires: Sailing (Navigation) 3.', 'techniques': [{'rank': 0, 'name': 'The Fortunes’ Guidance', 'effect': 'When confronted with difficult weather, spend a Void Point as a Simple Action to negate the conditions in an area School Rank × 20 feet in all directions. In a skirmish, effect lasts School Rank Rounds; outside combat, School Rank hours. If the weather effect is a spell, may only negate spells of Mastery Level equal to or less than School Rank, and must also expend spell slots equal to the Mastery Level in addition to the Void Point.'}]},
    {'name': 'Mantis Orochi Rider', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Mantis Basic/Advanced School Technique at Insight Rank 6, or a “blank” Insight Rank after attaining Rank 5 in any Mantis Basic School. If trained entirely in Mantis Shugenja Schools, may take at Rank 5 (treated as Shugenja Path). Requires: Water 4, Athletics 5, Lore: Spirit Realms 5. Must be specially chosen and successfully bond with an Orochi.', 'techniques': [{'rank': 0, 'name': 'The Orochi Pact', 'effect': 'Gain an Orochi sea-serpent as a mount (GM-controlled NPC that generally obeys your commands). +2k0 to Athletics rolls. Two Ranks of Magic Resistance against hostile Water Magic. While riding the Orochi, hold your breath underwater for twice the normal amount of time.'}]},
    {'name': 'Mantis Whirlwind Fighters', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Yoritomo Bushi 4. Requires: Knives (Kama) 5.', 'techniques': [{'rank': 0, 'name': 'Waves Rush to Shore', 'effect': 'When fighting with a kama in each hand, add your Knives Skill Rank to your Armor TN and gain +3k0 to damage rolls with kama.'}]},
    {'name': 'Moshi Guardian of the Sun: Centipede/Moshi', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Mantis Bushi 1. Benefit: +1 Stamina | Skills: Athletics, Defense, Jiujutsu, Kenjutsu, Lore: Theology, Spears, any 1 High or Bugei Skill | Honor: 6.5 | Outfit: Ashigaru or Light Armor, Sturdy Clothing, Daisho, Bow or Knife, Traveling Pack, 5 koku. Special: Prior to the Moshi joining the Mantis, may also replace Insight Rank 1 for a Moshi bushi without a school.', 'techniques': [{'rank': 0, 'name': 'Defended as the Sun', 'effect': 'When defending a Moshi personage or holding, choose at the start of each Turn: gain +1k0 to your attack roll, or add +1k1 to the Armor TN of a person or object you are defending with the Guard Action.'}]},
    {'name': 'Rajya ke Varisa (cross-clan)', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Hida Bushi 4, Shinjo Bushi 4, Moto Bushi 4, Yoritomo Bushi', 'techniques': [{'rank': 0, 'name': 'Legacy of the Kshatriya', 'effect': 'Twice per skirmish, take a Free Action to spend a Void Point before an attack. If the attack succeeds, add unkept dice to the damage roll equal to your Lore: Theology Skill Rank.'}]},
    {'name': 'Sisters of the Sacred Light: Centipede/Moshi', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Asahina Shugenja 2, Isawa Shugenja (Air) 2, Moshi Shugenja', 'techniques': [{'rank': 0, 'name': 'Light Banishes Lies', 'effect': 'When attempting to Banish the kami of Air, require only 2 Raises on the Sense spell (instead of 3) and only 3 Raises on the Commune spell (instead of 5).'}]},
    {'name': 'Student of the Cliff’s Edge', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Tsuruchi Bounty Hunter 3 or Yoritomo Bushi 4. Requires: Agility 4, Chain Weapons 5.', 'techniques': [{'rank': 0, 'name': 'Howl of the Cliff’s Edge', 'effect': 'When using a kusarigama to make a Knockdown or Disarm maneuver, gain +2k1 to the attack roll. Call three Raises on a kusarigama attack to Entangle an opponent up to 15’ away. The condition lasts until you voluntarily release the foe (Free Action) or the foe succeeds in a Contested Strength Roll against you (Simple Action).'}]},
    {'name': 'The College of Clarity: Moshi/Centipede', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any School 2. Requires: Fire 3, Meditation 2.', 'techniques': [{'rank': 0, 'name': 'The Clarity of Fire', 'effect': 'Meditate for at least half an hour and roll Meditation/Fire (TN 15). On success, gain the Clear Thinker and Precise Memory Advantages for hours equal to your Fire Ring. If you already have either Advantage, their bonuses increase by +1k0. Special: May instead gain +1k0 to one Iaijutsu (Focus)/Void Roll made during the same period.'}]},
    {'name': 'Tsuruchi Master Bowman: Wasp/Tsuruchi', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: N/A (Rank 6). Requires: Kyujutsu 7. Must have School Rank 5 in either Tsuruchi Archer or Tsuruchi Bounty Hunter, and be selected by Tsuruchi sensei.', 'techniques': [{'rank': 0, 'name': 'The Way of the Archer', 'effect': 'When using a bow, range is increased by 150’ (applied before the 50% bonus from Kyujutsu Rank 5). Raises with a bow are no longer limited by Void Ring (or Skill Rank if you have Great Potential). Called Shots cost half the normal number of Raises (rounded up).'}]},
    {'name': 'Tsuruchi Swordsman: Wasp/Tsuruchi', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Tsuruchi Archer 4, Tsuruchi Bounty Hunter 4. Requires: Kenjutsu 3.', 'techniques': [{'rank': 0, 'name': 'Ascendancy of Steel', 'effect': 'Make a melee attack as a Simple Action rather than a Complex Action when wielding a sword.'}]},
    {'name': 'Yoritomo Emissaries', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Yoritomo Courtier 4. Requires: Etiquette (Courtesy) 4.', 'techniques': [{'rank': 0, 'name': 'Intrepid Negotiator', 'effect': 'When making an Etiquette or Sincerity roll, spend a Void Point to add Willpower in unkept dice to the roll. If specifically using Etiquette (Courtesy), add Willpower in kept dice instead.'}]},
    {'name': 'Yoritomo Scoundrel', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Bushi', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Yoritomo Bushi 2. Requires: Commerce 2, Sailing 2.', 'techniques': [{'rank': 0, 'name': 'Revel in Villainy', 'effect': 'Whenever you spend a Void Point to enhance an Athletics, Commerce, Sailing, Sincerity, or Low Skill Roll, gain an additional bonus to the roll equal to twice your School Rank.'}]},
    {'name': 'Yoritomo Sculptors', 'clan': 'Mantis', 'category': 'alternate', 'keywords': ['Artisan'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Mantis Bushi or Courtier 2. Requires: Artisan: Sculpture or Craft: Sculpture 4.', 'techniques': [{'rank': 0, 'name': 'Watanabe’s Legacy', 'effect': '+1k1 when using Artisan: Sculpture and Craft: Sculpture. May ignore all circumstantial or environmental penalties (distractions, weather, noise, etc.) on rolls with those two Skills.'}]},
    {'name': 'Chuda Shugenja: Snake Clan (Historical)', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Willpower', 'skills': 'Calligraphy (Cipher), Etiquette, Lore: Maho, Lore: Shadowlands, Spellcraft, any 2 Skills', 'honor': '4.5', 'outfit': 'Robes, Wakizashi, Knife, Scroll Satchel, Traveling Pack, 3 koku', 'affinity': 'Earth / Air', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'To Punish the Wicked', 'effect': 'Isawa Chuda was a ruthless persecutor of the Shadowlands, and his techniques live on in those who bear his name. Spend a Void Point as a Free Action to negate an amount of Reduction equal to your School Rank from one targeted opponent. Add your School Rank to the total of any damage roll made by a spell you cast against a target with the Shadowlands Taint.'}]},
    {'name': 'Fuzake Shugenja: Monkey Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['SE'], 'benefit': '+1 Awareness', 'skills': 'Calligraphy, Defense, Etiquette, Lore: Theology, Medicine, Spellcraft, any one High or Merchant Skill', 'honor': '5.5', 'outfit': 'Robes, Wakizashi, Knife, Scroll Satchel, Traveling Pack, 2 koku', 'affinity': 'Earth / Fire', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'The Sideways Path', 'effect': 'Fuzake Garou was originally trained by the Kuni but spent his life protecting and healing those around him. When casting a spell that heals Wounds or cures poison or illness (such as Path to Inner Peace or Peace of the Kami), you may expend one or more Earth spell slots in addition; each such slot awards a Free Raise on your Spell Casting Roll.'}]},
    {'name': 'Heichi Bushi: Boar Clan (Historical)', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Strength', 'skills': 'Athletics, Defense, Hunting, Intimidation, Kenjutsu, Spears (Mai Chong), any one Bugei Skill', 'honor': '3.0', 'outfit': 'Light or Heavy Armor, Sturdy Clothing, Daisho, any Spear, Traveling Pack, 3 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Charge of the Boar', 'effect': 'If you are in Full Attack stance, you may ready a medium weapon or spear as a Free Action. When wielding a spear, you gain +0k1 to damage rolls.'}, {'rank': 2, 'name': 'The Strength of Opposition', 'effect': 'You may call two Raises to Entangle an opponent with a Mai Chong, or three Raises to Entangle with another spear-class weapon.'}, {'rank': 3, 'name': 'The Speed of the Boar', 'effect': 'You may attack as a Simple Action when wielding a spear.'}, {'rank': 4, 'name': 'The Anger of the Boar', 'effect': 'Spend a Void Point during the Reactions segment to reduce your Wound TN penalty by one Wound Rank for the remainder of the skirmish.'}, {'rank': 5, 'name': 'Beyond the Mountains', 'effect': 'If you are in Full Defense Stance, you may make one normal attack with a spear or Samurai-keyword weapon as a Free Action, ignoring the restriction of Full Defense. This attack gains +2k0 to the attack roll.'}]},
    {'name': 'Ichiro Bushi: Badger Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Strength', 'skills': 'Athletics, Commerce, Defense, Heavy Weapons, Jiujutsu, Kenjutsu (Katana), any High or Bugei Skill', 'honor': '3.5', 'outfit': 'Light or Heavy Armor, Sturdy Clothing, Daisho, any Heavy Weapon or Polearm, Traveling Pack, 3 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Transcend the Mountain', 'effect': 'You may re-roll any Skill or Trait roll using Strength, keeping the second result. You suffer no movement or combat penalties for Moderate terrain, and only half the normal penalty for Difficult terrain.'}, {'rank': 2, 'name': 'Strength of the Badger', 'effect': 'A number of times per session equal to your Strength Rank, you may re-roll a damage roll, keeping the better result.'}, {'rank': 3, 'name': 'Crushing Blow', 'effect': 'You may ignore the effects of armor on an opponent’s Armor TN. Your unarmed attacks may ignore 1 Rank of your target’s Reduction.'}, {'rank': 4, 'name': 'Crashing Stones', 'effect': 'Your attacks with Samurai weapons or unarmed strikes are Simple Actions.'}, {'rank': 5, 'name': 'Return the Strike', 'effect': 'At the start of a skirmish, before Initiative is rolled, you may lower your Initiative total by 20 for the duration. In exchange, add your Strength Rank in unkept dice to both attack and damage rolls for the first two Rounds.'}]},
    {'name': 'Kasuga Smuggler: Tortoise Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['Courtier', 'CR'], 'benefit': '+1 Awareness', 'skills': 'Commerce, Etiquette, Investigation (Notice), Lore: Underworld, Sincerity (Deceit), Stealth, any one High/Merchant/Low Skill', 'honor': '2.0', 'outfit': 'Extravagant Clothing, Wakizashi, any 1 weapon, Calligraphy Set, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Way of the Tortoise', 'effect': 'Learn an additional gaijin language free with every purchase of the Languages Advantage. No Honor point loss for Low Skills or Glory point loss for Commerce in public when acting on clan duty. +2k0 to all Social Skill Rolls when dealing with heimin or hinin.'}, {'rank': 2, 'name': 'The Shell of the Tortoise', 'effect': 'Any clan or Imperial samurai who physically attacks or openly slanders you without provocation immediately loses a number of Honor points equal to twice your School Rank.'}, {'rank': 3, 'name': 'The Eyes of the Emperor', 'effect': 'When acting on behalf of your clan, roll additional unkept dice equal to your School Rank on all Low Skills in which you have at least one Skill Rank (including School Skills used as Low Skills, such as Sincerity with Deceit Emphasis).'}, {'rank': 4, 'name': 'Hand in Hand', 'effect': 'Once per session, if you have access to local heimin or hinin, roll Lore: Underworld / Awareness at TN 25 to learn one useful piece of information (GM’s choice) that cannot be learned any other way.'}, {'rank': 5, 'name': 'The Tortoise Smiles', 'effect': 'When making a Skill Roll with any of your six School Skills, your maximum Raises are not limited by your Void. A number of times per session equal to your Void Ring, gain +5k0 on any School Skill roll (stacks with Rank 3).'}]},
    {'name': 'Komori Shugenja: Bat Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Awareness', 'skills': 'Calligraphy (Cipher), Lore: Ancestors, Lore: Theology, Meditation, Spellcraft, Tea Ceremony, any one High Skill', 'honor': '4.5', 'outfit': 'Robes, Wakizashi, any 1 weapon, Scroll Satchel, Traveling Pack, 3 koku', 'affinity': 'Air / Earth', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'The Kami’s Whispers', 'effect': 'The Komori practice the rituals of the koumori spirits and ferry messages via the kami. Expend one spell slot to send a whispered message to any individual known to you. The message may be no longer than thirty seconds per School Rank in length, and may be delivered a maximum distance of School Rank x 100 miles.'}]},
    {'name': 'Morito Bushi: Ox Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Agility', 'skills': 'Defense, Horsemanship, Hunting (Tracking), Kenjutsu, Lore: Kolat, Lore: Underworld, any one Skill', 'honor': '3.5', 'outfit': 'Light or Heavy Armor, Sturdy Clothing, Daisho, Heavy Weapon or Polearm, Horse (Rokugani Pony), Traveling Pack, 3 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Legacy of the Four Winds', 'effect': 'Add +1k0 to your Initiative if Mounted at the start of combat. Add +1k0 to attack rolls while mounted.'}, {'rank': 2, 'name': 'The Wind Blows Many Ways', 'effect': 'At the start of combat, declare a number of Bugei Skills equal to your School Rank. Add +1k0 to all rolls involving the chosen Skills.'}, {'rank': 3, 'name': 'Thunder and Fury', 'effect': 'You may make attacks as a Simple Action while Mounted.'}, {'rank': 4, 'name': 'The Blade Upon the Wind', 'effect': 'Once per skirmish, spend a Void Point as a Free Action to set your Initiative Score equal to that of any other participant. Afterward your Initiative Score is reduced by 5 during each Reactions Stage until the encounter ends.'}, {'rank': 5, 'name': 'Fast and Furious', 'effect': 'While attacking an opponent with lower Initiative, add +2k2 to all attack and damage rolls.'}]},
    {'name': 'Suzume Bushi: Sparrow Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Willpower', 'skills': 'Calligraphy, Kenjutsu (Katana), Lore: History, Lore: Theology, Perform: Storytelling, any one Lore Skill, any one Skill', 'honor': '6.5', 'outfit': 'Light Armor, Sturdy Clothing, Daisho, any 1 weapon, Traveling Pack, 3 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'All Things in Time', 'effect': 'At the beginning of the Combat Round, before the first character has taken his Turn, you may reduce your Initiative by 5 to add +1k0 to all attack and damage rolls for the Round.'}, {'rank': 2, 'name': 'Purity of Chi', 'effect': 'Add +5 to your Armor TN against creatures and against human opponents with lower Honor.'}, {'rank': 3, 'name': 'Wisdom is the Greatest Weapon', 'effect': 'Spend a Void Point to add your Honor Rank to any Perform or Lore Skill Roll.'}, {'rank': 4, 'name': 'Quiet Spirit, Steady Blade', 'effect': 'You may make melee attacks as a Simple Action while in the Attack Stance.'}, {'rank': 5, 'name': 'Slow and Deadly', 'effect': 'During the Round following your adoption of the Center Stance, add +10 to your attack and damage rolls. Does not apply during iaijutsu duels.'}]},
    {'name': 'Toku Bushi: Monkey Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Willpower', 'skills': 'Athletics, Defense, Hunting, Investigation (Search), Kenjutsu, Lore: History, any one High or Bugei Skill', 'honor': '5.5', 'outfit': 'Light Armor, Sturdy Clothing, Daisho, any 1 Weapon, Traveling Pack, 3 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Toku’s Lesson', 'effect': 'Add +1k0 to all Skill Rolls with a TN of 25 or higher (including attack rolls). All Wound Penalties are reduced by an amount equal to your Willpower plus double your School Rank.'}, {'rank': 2, 'name': 'The Strength of One Man', 'effect': 'While facing multiple opponents or an enemy with a higher Insight Rank, add +1k1 to attack and damage rolls.'}, {'rank': 3, 'name': 'Courage Above All', 'effect': 'You may make melee attacks as a Simple Action instead of a Complex Action.'}, {'rank': 4, 'name': 'Forge Your Own Fate', 'effect': 'Spend a Void Point when suffering Wounds to force your opponent to drop his two highest damage dice, even if this reduces kept dice (minimum 1k1).'}, {'rank': 5, 'name': 'Fortune Favors the Mortal Man', 'effect': 'Once per Round, spend a Void Point to reroll any roll, adding +2k1 to the new roll. You may keep either result.'}]},
    {'name': 'Tonbo Shugenja: Dragonfly Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Perception', 'skills': 'Calligraphy, Courtier, Etiquette, Meditation (Void Recovery), Sincerity, Spellcraft, any one High Skill', 'honor': '4.5', 'outfit': 'Robes, Wakizashi, Knife, Scroll Satchel, Traveling Pack, 3 koku', 'affinity': 'Water / Fire', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'Guided by Fate', 'effect': 'The kami’s whispers can be powerful tools in court. Expend one spell slot to gain +1k0 on one Social Skill Roll. You may never spend more spell slots than your School Rank to augment a single roll. You gain a Free Raise on any spell with the Divination keyword.'}]},
    {'name': 'Tsi Smith: Oriole Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['Artisan', 'CR'], 'benefit': '+1 Intelligence', 'skills': 'Any one Artisan Skill, Commerce, two ranks in any one Craft Skill, Defense, any one Weapon Skill, any one High/Bugei/Merchant Skill', 'honor': '4.5', 'outfit': 'Sensible Clothing, Wakizashi, Calligraphy Set, Traveling Pack, 3 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Tools of the Fortunes', 'effect': 'All Craft Skills are School Skills for you. Whenever you make a Craft Skill Roll against a TN of 10 + (School Rank x 5) or higher, gain 1 Glory point for succeeding, plus 1 Glory point for every increment of 5 by which you exceed the TN.'}, {'rank': 2, 'name': 'Tsi Xing Guo’s Blessing', 'effect': 'When wielding or using one of your own creations, you gain +2k1 for Void Points spent on relevant Skill Rolls instead of the usual +1k1. When an item you created is given as a gift among samurai, both you and the gift-giver gain Glory points equal to your School Rank.'}, {'rank': 3, 'name': 'A Crafter’s Dedication', 'effect': 'When crafting, halve the price for purposes of determining creation time. When someone in your presence uses an item you created, take a Complex Action to grant them +xk1 (where X is your School Rank) on the relevant Skill Roll.'}, {'rank': 4, 'name': 'Exhaustive Knowledge', 'effect': 'Spend a Void Point as a Free Action to make all attacks with a weapon you created as Simple Actions for a number of Rounds equal to your School Rank.'}, {'rank': 5, 'name': 'Star-filled Steel', 'effect': 'Once per day, upon completing a weapon, spend all your Void Points to create a Sacred Weapon (Tsi Blade, Tsi Tetsubo, etc.) with one of the following qualities: Balanced (+1k0 to attack rolls), Swift (+5 Initiative while wielding), or Unbreakable (weapon cannot be broken). At GM’s option, a truly gifted Tsi smith may also make a weapon Radiant (treat as jade for harming Invulnerable creatures).'}]},
    {'name': 'Usagi Bushi: Hare Clan', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Reflexes', 'skills': 'Athletics (Running), Defense, Hunting, Jiujutsu, Kenjutsu, Lore: Maho (may replace with Lore: Kolat after Clan War era), any one High or Bugei Skill', 'honor': '4.0', 'outfit': 'Ashigaru or Light Armor, Sturdy Clothing, Daisho, Bow (with 20 Arrows) or Knife, Traveling Pack, 3 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Speed of the Hare', 'effect': 'In any situation where you have room to maneuver (GM’s discretion), add your Athletics Skill Rank to your Armor TN except when in Full Attack or Center stance. Your Water Ring is considered 1 higher for Move actions.'}, {'rank': 2, 'name': 'Leap of the Hare', 'effect': 'In Full Attack stance, you may leap forward and attack an opponent up to 15’ away without taking a Move Action. All attacks this turn must target that opponent.'}, {'rank': 3, 'name': 'Swift as Lightning', 'effect': 'Your attacks with unarmed strikes, knives, or Samurai-keyword weapons are Simple Actions.'}, {'rank': 4, 'name': 'Kick of the Hare', 'effect': 'You may now perform your Rank 2 Technique while in the Attack stance instead of Full Attack. If performed in Full Attack, your second attack may target another opponent within 15’ of the first.'}, {'rank': 5, 'name': 'Reichin’s Style', 'effect': 'You may perform the Feint Maneuver for only 1 Raise, and your damage bonus from a successful Feint is not limited to your Insight Rank x 5.'}]},
    {'name': 'Yotsu Bushi: Tiger Clan (Ronin Family / Otosan Uchi Guardians)', 'clan': 'Minor Clan', 'category': 'basic', 'keywords': ['IH'], 'benefit': '+1 Agility', 'skills': 'Commerce, Hunting, Kenjutsu, Kyujutsu, Lore: Gaijin or Lore: Shadowlands, Stealth (Sneaking), one Low or Bugei Skill', 'honor': '5.5', 'outfit': 'Ashigaru or Light Armor, Sturdy Clothing, Daisho, any 2 weapons, Traveling Pack, 4 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Tiger’s Tread', 'effect': 'You do not lose Honor points for using Ambush or Shadowing against enemies of the Empire (GM’s discretion). In urban environments (including ruins), gain +1k0 to Stealth rolls and add your Stealth Skill Rank to your Armor TN.'}, {'rank': 2, 'name': 'The Tiger’s Pounce', 'effect': 'On the first Round of a skirmish, add your Stealth Skill Rank to your Initiative roll total (ends at Reactions stage of Round 1).'}, {'rank': 3, 'name': 'Rending Claws', 'effect': 'When fighting with a Samurai weapon you may make attacks as a Simple Action.'}, {'rank': 4, 'name': 'Shelter the Blameless', 'effect': 'During any Round when you are actively defending or protecting others (GM’s discretion), gain one bonus Void Point for that Round. Unspent Void Points from this Technique are lost at end of Round.'}, {'rank': 5, 'name': 'The Tiger’s Fangs', 'effect': 'On the first Round of a skirmish, you may declare Maneuvers for one less Raise.'}]},
    {'name': 'Minor Clan Defender', 'clan': 'Minor Clan', 'category': 'advanced', 'keywords': ['Bushi', 'EE'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Know No Boundaries', 'effect': 'Spend a Void Point to temporarily gain 2 Ranks in Status, forcing others to recognize your talents. This effect lasts 1 hour.'}, {'rank': 2, 'name': 'The Speed of Certainty', 'effect': 'Once per Round, spend a Void Point to make one melee attack as a Free Action. You may make no other attacks this Round.'}, {'rank': 3, 'name': 'The Strength of Humility', 'effect': 'Make melee attacks as a Simple Action with Samurai-keyword weapons. If you already have this ability with such weapons, choose any one other melee weapon type: you may also attack with those as Simple Actions.'}]},
