    {'name': 'Emerald Magistrate', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': ['CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Bushi, Courtier, or Shugenja School, Rank 4', 'techniques': [{'rank': 0, 'name': 'Honor Is My Shield', 'effect': 'Gain Reduction equal to half your Honor Rank (rounded up). This stacks with Reduction from all other sources including armor.'}]},
