    {'name': 'Imperial Legionnaire', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': ['CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Bushi School, Rank 2', 'techniques': [{'rank': 0, 'name': 'Strength of the Empire', 'effect': 'When fighting alongside other Imperial Legionnaires, or alongside Emerald or Jade Magistrates, when you spend a Void Point to enhance a roll you also gain a bonus to the roll equal to the number of allied legionnaires and/or magistrates within 25 feet.'}]},
