    {'name': 'Second City Guardsman', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Bushi School at Rank 2', 'techniques': [{'rank': 0, 'name': 'The Governor’s Armor', 'effect': 'Your Status Rank is considered one higher throughout the Colonial territories. When fighting within the Second City or another city-sized Colonial settlement while in Defense or Full Defense Stance, if your opponent attacks and misses you before your Turn for the Round, you may immediately change your Stance to Attack (losing all Armor TN bonuses from your previous Stance).'}]},
    {'name': 'Serpent Hunter', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Bushi School Rank that awards an attack as a Simple Action', 'techniques': [{'rank': 0, 'name': 'Blood of the Serpent', 'effect': 'Make attacks as a Simple Action with Samurai-quality melee weapons. When facing a Naga opponent of any kind, make attacks as a Simple Action with any weapon.'}]},
    {'name': 'The Amethyst Champion', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': ['CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any: may voluntarily take upon advancing in Rank or wait until a later Rank', 'techniques': [{'rank': 0, 'name': 'The Emperor’s Voice', 'effect': 'The Amethyst Champion brings the voice of the Emperor to those who cannot attend Imperial Court. As a Free Action, spend a Void Point to temporarily gain the ability to use any courtier Technique that has been used against you in the past seven days.'}]},
    {'name': 'The Bloodspeaker Technique', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': [], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any', 'techniques': [{'rank': 0, 'name': 'Iuchiban’s Method', 'effect': 'Learn two Maho spells of your choice and gain a Free Raise for Spell Casting Rolls with Maho spells. When casting a Maho spell, reduce the Taint you gain by 1 for every 2 additional Wounds you take (minimum 1 point of Taint). If using someone else’s blood to power the spell, you may instead transfer the Taint onto that person at the rate of 1 point per 2 extra Wounds inflicted: reducing your own Taint gain to 0.'}]},
    {'name': 'The Emerald Champion', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': ['CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any: may voluntarily take upon advancing in Rank or wait until a later Rank', 'techniques': [{'rank': 0, 'name': 'The Emperor’s Hand', 'effect': 'Gain +1k1 on all High and Bugei Skill Rolls and an additional +1k0 on all School Skills. Gain bonus Void Points per day equal to your highest Ring; these may be granted to any one subordinate or ally in line of sight as a Free Action (once per Round). You may not use these bonus Void Points yourself.'}]},
    {'name': 'The Jade Champion', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': ['CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any: may voluntarily take upon advancing in Rank or wait until a later Rank', 'techniques': [{'rank': 0, 'name': 'The Emperor’s Will', 'effect': 'Gain a Free Raise on all Spell Casting Rolls. When confronting an opponent who practices outlawed magic (maho, yobanjin shamanism, gaijin sorcery, etc.) or possesses corrupt supernatural abilities (Shadowlands Taint or corruption by the Lying Darkness), gain an additional Free Raise on your Spell Casting Roll.'}]},
    {'name': 'The Ruby Champion', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': ['CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any: may voluntarily take upon advancing in Rank or wait until a later Rank', 'techniques': [{'rank': 0, 'name': 'Master of the Dojo', 'effect': 'When fighting alongside allies under your command, spend a Void Point as a Complex Action to allow any one ally within line of sight to use one of your Techniques as if that ally were a member of your School at equivalent rank. This effect lasts until the start of your next Turn.'}]},
    {'name': 'The Topaz Champion', 'clan': 'Miscellaneous', 'category': 'alternate', 'keywords': ['CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any: may voluntarily take upon advancing in Rank or wait until a later Rank', 'techniques': [{'rank': 0, 'name': 'Soul of Promise', 'effect': 'When you advance in Insight Rank and into this Path, you gain the Technique it would normally replace. You also gain a number of bonus Void Points per day equal to your highest Ring. These may be spent like normal Void Points but only to enhance School Skill Rolls.'}]},
    {'name': 'Agasha Shugenja', 'clan': 'Phoenix', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Intelligence', 'skills': 'Calligraphy (Cipher), any one Craft Skill, Defense, Etiquette, Lore: Theology, Spellcraft, any one High or Bugei Skill', 'honor': '4.5', 'outfit': 'Robes, Wakizashi, any 1 weapon, Scroll Satchel, Traveling Pack, 5 koku', 'affinity': 'Fire / Water | Starting Spells: Sense, Commune, Summon, 3 Fire, 2 Earth, 1 Air', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'Elements of All Things', 'effect': 'When casting a spell, spend a Void Point to use a different Ring of your choosing rather than the appropriate Ring for that spell. The spell uses a slot for the Ring actually used to cast it. Free Raise on any spell with the Craft keyword.'}]},
    {'name': 'Asako Henshin', 'clan': 'Phoenix', 'category': 'basic', 'keywords': ['Monk'], 'benefit': '+1 Willpower', 'skills': 'Calligraphy, Jiujutsu, Lore: Elements (pick an emphasis), Lore: Theology, Meditation 2, any 1 Skill (must not be a Low Skill)', 'honor': '5.5', 'outfit': 'Robes, Bo, Scroll Satchel, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Four Mysteries', 'effect': 'Simple Action: increase or decrease both Traits associated with one Ring by your School Rank. Lasts minutes equal to your Insight Rank; usable up to five times your Insight Rank per day. May alter another’s Traits by half School Rank (minimum 1). Altering an unknowing or unwilling target requires a Contested Willpower Roll. Trait reductions do not affect Ring values.'}, {'rank': 2, 'name': 'The Riddle of Earth', 'effect': 'Simple Action: invoke Earth’s blessing; become immune to all Conditional Effects (excluding Grappled and Mounted) for hours equal to your Earth Ring.'}, {'rank': 3, 'name': 'The Riddle of Air', 'effect': 'Simple Action: invoke Air’s blessing for hours equal to your School Rank. You cannot be deceived by any illusion or false image: you perceive them as transparent falsehoods. If an illusion was created by a spell of higher Mastery Level than your Insight Rank, engage in a Contested Air Roll with the caster; if you lose, the falsehood is not perceived.'}, {'rank': 4, 'name': 'The Riddle of Fire', 'effect': 'Complex Action: invoke Fire’s blessing to increase kept dice on unarmed damage rolls to your Fire Ring for Rounds equal to your School Rank. Alternatively, when struck by a melee attack spend a Void Point to force a Contested Fire Ring Roll: on success, reduce the number of damage dice your opponent rolls by your Fire Ring.'}, {'rank': 5, 'name': 'The Riddle of Water', 'effect': 'Roll Lore: Elements (Water)/Water (TN 20). On success, take one Complex and one Simple Action per Turn, or three Simple Actions per Turn.'}]},
    {'name': 'Asako Loremaster', 'clan': 'Phoenix', 'category': 'basic', 'keywords': ['Courtier', 'CR'], 'benefit': '+1 Intelligence', 'skills': 'Courtier, Etiquette (Courtesy), Lore: History, Lore: Theology (Fortunes), Meditation, Sincerity, any one Lore Skill', 'honor': '6.5', 'outfit': 'Sensible Clothing, Wakizashi, Calligraphy Set, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Temple of the Soul', 'effect': 'Free Raise on any Lore Skill Roll. When spending a Void Point on an Etiquette Skill Roll, gain +3k1 instead of the normal +1k1.'}, {'rank': 2, 'name': 'From the Ashes', 'effect': 'After spending at least one day observing a particular court, roll Lore: History/Perception (TN 20) to gain +2k0 to all Social Skill Roll totals for the next two days while remaining in that court. Reactivate with another roll when it expires: no additional observation days required.'}, {'rank': 3, 'name': 'Voice of the Universe', 'effect': 'Spend an hour conversing with an ally and roll Lore: History/Intelligence (TN 25). On success, that ally may add your Lore: History Skill Rank to any Social Skill Roll totals within the next twenty-four hours. Raise twice to affect one additional ally who also participates.'}, {'rank': 4, 'name': 'Invincible Mind', 'effect': 'Any time you fail a Contested Social Skill Roll to resist influence on your emotions, opinions, or behavior, reroll using Intelligence as the Trait instead of whichever Trait was originally required. Must keep the second result. Cannot resist Fear with this Technique.'}, {'rank': 5, 'name': 'Wisdom of the Ages', 'effect': '+5k0 to the total of any Lore Skill Roll, including rolls for other School Techniques.'}]},
    {'name': 'Isawa Shugenja', 'clan': 'Phoenix', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Intelligence', 'skills': 'Calligraphy (Cipher), Lore: Theology, any one Lore Skill, Medicine, Meditation, Spellcraft, any one High Skill', 'honor': '4.5', 'outfit': 'Robes, Wakizashi, any 1 weapon, Scroll Satchel, Traveling Pack, 5 koku', 'affinity': 'May select any element including Void as Affinity. No Deficiency.', 'prereq': '', 'techniques': [{'rank': 0, 'name': 'Isawa’s Gift', 'effect': 'Free Raise on all Spell Casting Rolls for spells of the element chosen as your Affinity.'}]},
    {'name': 'Shiba Artisan', 'clan': 'Phoenix', 'category': 'basic', 'keywords': ['Courtier', 'EE'], 'benefit': '+1 Intelligence', 'skills': 'Artisan (pick 2), Calligraphy, Etiquette, Lore (pick 1), Sincerity, any 1 High or Bugei Skill', 'honor': '4.5', 'outfit': 'Sensible Clothing, Wakizashi, tools for chosen specialty, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Soul of Brilliance', 'effect': 'Select one Artisan Skill. When spending a Void Point on a roll using that Skill, gain +2k2 instead of the normal +1k1.'}, {'rank': 2, 'name': 'The Way of Sincerity', 'effect': 'Once per month, make an Artisan Skill Roll (TN 15). Gain XP equal to the amount your roll exceeds the TN: these XP may only be spent to purchase the Allies Advantage (subject to GM approval). These Allies last weeks equal to your School Rank.'}, {'rank': 3, 'name': 'The Art Speaks', 'effect': 'Choose one Artisan Skill. When called to make a Social Skill Roll, you may use your Artisan Skill Ranks in place of the required Social Skill. No Mastery Level benefits apply. GM has final say on applicability.'}, {'rank': 4, 'name': 'Bounty of the Craft', 'effect': 'Once per day, make an Artisan Skill Roll (TN 30). On success, you and up to School Rank other people present all regain all Void Points. Requires at least fifteen minutes of ritualized presentation. Cannot be used in the Shadowlands.'}, {'rank': 5, 'name': 'The Touch of Destiny', 'effect': 'When your work is on display in court or in a lord’s home, all present gain one additional Void Point. If you are present, you gain two additional Void Points instead and may deny the benefit to anyone in attendance. Maximum one additional Void Point per person per day (two for you).'}]},
    {'name': 'Shiba Bushi', 'clan': 'Phoenix', 'category': 'basic', 'keywords': ['CR'], 'benefit': '+1 Agility', 'skills': 'Defense, Kenjutsu, Kyujutsu, Meditation (Void Recovery), Spears, Theology, any one Bugei or High Skill', 'honor': '5.5', 'outfit': 'Light Armor, Sturdy Clothing, Daisho, any 1 weapon, Traveling Pack, 5 koku', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'The Way of the Phoenix', 'effect': 'When spending a Void Point for +1k1 on a roll, you may instead spend 2 Void Points to gain +2k2. You may Guard as a Free Action; however, your target only adds +5 to his Armor TN instead of +10.'}, {'rank': 2, 'name': 'Dancing With the Elements', 'effect': 'When you assume your Stance, choose a target within 30’. Whenever your target casts or is the target of a spell, you may increase or decrease the TN by 5. Additionally, whenever you are the target of a spell, you may increase or decrease the TN by 5.'}, {'rank': 3, 'name': 'One With the Void', 'effect': 'Automatically activates during the Reactions Stage if any character spent a Void Point this Combat Round: you regain one Void Point (may temporarily exceed maximum; excess lost after combat). Activates only twice per skirmish.'}, {'rank': 4, 'name': 'Move With the World', 'effect': 'Make attacks as a Simple Action instead of a Complex Action with Polearms, Spears, or weapons with the Samurai keyword.'}, {'rank': 5, 'name': 'Touch of the Void', 'effect': 'For every Void Point you spend, gain the effects of spending two (when applicable). You may now spend Void Points on enhancements twice in one Turn.'}]},
    {'name': 'Asako Inquisitors', 'clan': 'Phoenix', 'category': 'advanced', 'keywords': ['Monk'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Eye of the Inquisitor', 'effect': 'Considered one Rank higher in your original Shugenja School for casting purposes. Non-shugenja Inquisitors gain one Kiho (must meet prerequisites). Complex Action to prepare a disruption: later in the same skirmish, Free Action to force an opponent casting a spell to make 2 additional Raises on the casting roll (raises TN only).'}, {'rank': 2, 'name': 'The Trials of Jade', 'effect': 'When casting any spell, spend a Void Point for the spell to count as jade or crystal for purposes of reducing or defeating Reduction or Invulnerability. Non-casters may instead make a melee attack as a Simple Action when facing an opponent known to have violated Imperial laws regarding legal forms of magic.'}, {'rank': 3, 'name': 'Conviction of Purity', 'effect': 'Considered one Rank higher in your original Shugenja School for casting purposes. Non-shugenja Inquisitors gain one additional Kiho. May now prepare a disruption as a Simple Action instead of a Complex Action; disrupted opponents require 3 additional Raises rather than 2.'}]},
    {'name': 'Elemental Guard', 'clan': 'Phoenix', 'category': 'advanced', 'keywords': ['Shugenja', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': '', 'techniques': [{'rank': 1, 'name': 'Name of the Elements', 'effect': 'Shugenja School Rank considered one higher for casting spells of the Chosen Element. Spend a Void Point as a Free Action to add twice your chosen Ring Rank to your Armor TN for minutes equal to your Shugenja School Rank (visible elemental effect: flames, swirling water, rocklike skin, etc.).'}, {'rank': 2, 'name': 'Touch of the Elements', 'effect': 'Shugenja School Rank increases by one. Chosen Ring is considered two Ranks higher for determining spell slots in that Element per day.'}, {'rank': 3, 'name': 'Shape of the Elements', 'effect': 'Shugenja School Rank considered one higher for casting spells of the Chosen Element. Select one spell of the Chosen Element at Mastery Level 3 or greater: a number of times per day equal to your Void Ring, cast that spell with a single Simple Action.'}]},
    {'name': 'Acolytes of Snow', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Isawa Shugenja 2, any other Phoenix Shugenja 3. Requires: Lore: Yuki no Onna 3 or Water Affinity.', 'techniques': [{'rank': 0, 'name': 'The Maiden’s Icy Grasp', 'effect': 'May cast the following Earth spells as Water spells: Armor of Earth, Armor of the Emperor, Be the Mountain, Bonds of Ningen-do, Earth’s Stagnation, Grasp of Earth, Major Binding, Minor Binding, Wall of Earth. Spells create their effects from ice rather than earth or stone.'}]},
    {'name': 'Agasha Alchemist', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Agasha Shugenja 3. Requires: Fire 3, Spellcraft 3.', 'techniques': [{'rank': 0, 'name': 'Fury of the Elements', 'effect': 'Store a Fire spell with the Area of Effect “one target person” or “one target creature” in an alchemical preparation. Activated as a Simple Action (drink) or Complex Action (throw, using Athletics (Throwing)/Agility). By spending an additional spell slot of another element (not Void), also give the stored spell an additional elemental keyword or replace its Fire keyword with another. A spell may only gain one additional keyword this way.'}]},
    {'name': 'Asako Mediator', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Asako Loremaster 2, Shiba Bushi 2, Isawa Shugenja 2. Requires: Sincerity (Honesty) 3.', 'techniques': [{'rank': 0, 'name': 'Stand Down', 'effect': 'When samurai are preparing to enter formal hostilities, approach either or both parties and make a Contested Sincerity (Honesty)/Awareness vs Etiquette (Courtesy)/Willpower roll. On success, that party backs down without any loss of Glory. The GM may require Raises (1–5) for deeply committed parties and may award bonuses (+1k0 to +5k0) for honorable proposed solutions. Large-scale conflicts may only be delayed rather than prevented.'}]},
    {'name': 'Asako Philosopher', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Asako Loremaster 2. Requires: Courtier (Rhetoric) 2, Etiquette 3.', 'techniques': [{'rank': 0, 'name': 'The Winds of Rhetoric', 'effect': '+1k1 to the total of all Contested Social Skill Rolls using Etiquette.'}]},
    {'name': 'Asako Scholar', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Asako Loremaster 3, Asako Henshin 3. Requires: Investigation 3, Intelligence 4.', 'techniques': [{'rank': 0, 'name': 'The Hidden Patterns', 'effect': 'After spending at least one day observing patterns within a court or social setting, roll Investigation/Intelligence (TN 25). On success, rivals and enemies cannot benefit from Raises on Social Skill Rolls against you and cannot spend Void Points on Social Skill Rolls against you for 24 hours. Raise to share the benefit with friends and allies (one person per Raise).'}]},
    {'name': 'Elemental Legions', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Shiba Bushi 3. Requires: Lore: Elements (appropriate Ring) 2. Must be selected to serve in one of the Elemental Legions.', 'techniques': [{'rank': 0, 'name': 'Strength of the Five', 'effect': 'Select one non-Void Ring. When an allied shugenja within line of sight casts a spell of that Element, gain one bonus Void Point. Bonus Void Points may only be spent on rolls using that Element’s Traits, or element-specifically: Air: +10 Armor TN for one Round; Earth: reduce Wounds from one damage roll by 10; Fire: temporarily increase 1 Skill Rank from 0 to 1 for one roll; Water: exchange Initiative Score with one willing participant for the skirmish. Cannot exceed School Rank bonus Void Points; unused lost at skirmish end.'}]},
    {'name': 'Isawa Archaeologist', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Isawa Shugenja 2, Agasha Shugenja 2. Requires: Lore: Gaijin (Ivory Kingdoms) 3.', 'techniques': [{'rank': 0, 'name': 'There Are No Secrets', 'effect': 'When casting a non-damaging spell on an object, creature, or willing individual (not yourself) for which you have at least 3 Ranks in an applicable Lore Skill, gain +1k1 on the Spell Casting Roll. GM has final say on Lore Skill applicability.'}]},
    {'name': 'Isawa Seaguard', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Isawa Shugenja 3. Requires: Water 3, Air 3, Sailing 3.', 'techniques': [{'rank': 0, 'name': 'The Ward of the Sea', 'effect': 'While on board a ship on water, expend a Water or Air spell slot as a Complex Action to create a barrier of water and air around the ship. Lasts three Rounds. While active: ship has Reduction 10 against physical attacks, Reduction 25 against natural or magical fire-based attacks, and arrows to and from anyone on ship are obstructed, replicating the mechanical effects of Summoning the Gale.'}]},
    {'name': 'Isawa Temple Guardian', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Isawa Shugenja 3, Agasha Shugenja 3. Requires: Earth 4, Lore: Theology 3.', 'techniques': [{'rank': 0, 'name': 'Never This Sacred Ground Shall Fall', 'effect': 'When defending a sacred location (shrine, temple, or monastery), Free Raise on all Earth spells. When defending a sacred location, also spend a Void Point as a Free Action when casting any Earth spell that inflicts damage to grant it the Jade keyword.'}]},
    {'name': 'Isawa Tensai', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Isawa Shugenja 2. Requires: Lore: Elements 3, Spellcraft', 'techniques': [{'rank': 0, 'name': 'Embrace the Elements', 'effect': 'Gain an additional Affinity in any one element for which you already possess an Affinity. Gain a Deficiency in all other elements. Example: a Rank 1 Isawa with Fire Affinity advancing to this Technique becomes capable of casting Mastery Level 4 Fire spells but only Mastery Level 1 spells of all other elements.'}]},
    {'name': 'Kawaru Sages', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Any Phoenix Shugenja 2, Tonbo Shugenja 2. Requires: Divination (Kawaru) 3.', 'techniques': [{'rank': 0, 'name': 'The Veil of the Future', 'effect': 'At the start of each day, spend one hour in meditation and make a Divination Skill Roll (TN 15). On success, gain +1k0 bonus dice; Raise to gain additional bonus dice up to your Water Ring. Spend these dice on any Spell Casting Rolls made during the rest of the day. Unused dice lost at nightfall.'}]},
    {'name': 'Mist Legion', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Isawa Shugenja 3 (Air Affinity required).', 'techniques': [{'rank': 0, 'name': 'The World is a Canvas', 'effect': 'A number of times per day equal to your Insight Rank, spend a Void Point to cast Summon Fog or False Realm as a Simple Action.'}]},
    {'name': 'Nameless Ones', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja', 'IH'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Isawa Shugenja 3. Requires: Ishiken-do.', 'techniques': [{'rank': 0, 'name': 'Darkness Undone', 'effect': 'When casting any spell targeting an opponent with the Shadowlands Taint, expend one additional spell slot to lower the opponent’s Reduction by your School Rank. May expend multiple spell slots this way up to a maximum equal to your Void Ring. The lowered Reduction lasts until the beginning of your next Turn.'}]},
    {'name': 'Order of Chikai', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Shiba Bushi 5. Requires: Must have taken the Shiba Yojimbo Path at Rank 3 and be selected for service in the Order of Chikai.', 'techniques': [{'rank': 0, 'name': 'None Must Fall', 'effect': 'Designate one individual as your charge at the start of a skirmish. When your charge is targeted by an attack or spell, use the Shiba Yojimbo Technique as normal (Defense/Reflexes TN 25 to absorb the damage). Additionally, at the time of the roll you may spend a Void Point as a Free Action: if you succeed, the damage is negated entirely rather than simply transferred to you.'}]},
    {'name': 'Provincial Guard', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Bushi'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Shiba Bushi 2. Requires: Defense 2, Etiquette 2.', 'techniques': [{'rank': 0, 'name': 'Maintaining the Peace', 'effect': 'When in Defense or Full Defense Stance and spending a Void Point to augment your Armor TN, also add your Etiquette Skill Rank to your Armor TN.'}]},
    {'name': 'Sesai Ninja', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Ninja'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Shiba Bushi 2. Requires: Stealth 3.', 'techniques': [{'rank': 0, 'name': 'Anything For the Phoenix', 'effect': 'On a battlefield, +1k1 to all Stealth rolls and a Free Raise on all attack rolls made by surprise. When performing dishonorable acts on behalf of the Phoenix Clan, lose only half the normal Honor (rounded up).'}]},
    {'name': 'Shiba Advisor', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Courtier'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Asako Loremaster 3. Requires: Lore: History 3, Lore: War 3. Shiba family only.', 'techniques': [{'rank': 0, 'name': 'Lessons Never Forgotten', 'effect': 'Prior to a military task (patrol, scouting mission, attack, or bandit hunt), roll Lore: War/Intelligence (TN 25) or Lore: History/Intelligence (TN 35). On success, one allied bushi on the mission gains one Rank of Luck for the mission’s duration. Raise to bestow Luck on additional allies (not yourself), up to a maximum equal to your School Rank.'}]},
    {'name': 'Shiba Armorsmiths', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Bushi', 'Artisan'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Shiba Bushi 2. Requires: Craft: Armorsmithing 3, Defense', 'techniques': [{'rank': 0, 'name': 'Brilliant Steel', 'effect': '+1k0 on Craft rolls to create armor. When wearing armor and spending a Void Point to increase Armor TN by 10, also increase Armor TN by an additional amount equal to twice your Earth Ring.'}]},
    {'name': 'Shiba Illusionists', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Shugenja', 'Artisan'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Replaces: Isawa Shugenja 1 or Shiba Artisan 1. Special: Use the Trait benefit, Skills, Honor, and outfit of whichever school they attend. Always treated as having Air Affinity; gain 3 Air, 2 Water, and 1 Earth spell if this is their first Shugenja Technique.', 'techniques': [{'rank': 0, 'name': 'The Tejina’s Art', 'effect': 'Gain additional spell slots per day equal to your School Rank. These slots may only be used to cast Token of Memory, Flight of Doves, or Mists of Illusion.'}]},
    {'name': 'Shiba Yojimbo', 'clan': 'Phoenix', 'category': 'alternate', 'keywords': ['Bushi', 'CR'], 'benefit': '', 'skills': '', 'honor': '', 'outfit': '', 'affinity': '', 'prereq': 'Shiba bent the knee to man and swore to follow the Isawa at the inception of the Phoenix Clan. The Shiba Yojimbo is the epitome of that oath: he will die before he allows harm to his charge. Only the most honorable and selfless Shiba are selected, since the training requires a complete willingness to throw one’s life away without hesitation. Replaces: Shiba Bushi 3. Requires: Honor Rank 5.0+.', 'techniques': [{'rank': 0, 'name': 'Shiba’s Sacrifice', 'effect': 'At the start of any skirmish, designate one ally as your charge. Any time your charge is hit by a physical or targeted non-area-effect damage-causing spell, if you are within 10’ make a Defense/Reflexes roll (TN 25). On success, you take the damage instead of your charge. If you spend a Void Point to reduce this damage, it is reduced by 20 instead of the normal 10.'}]},
